export const UNIT4_SEGMENT_A_ITEMS = [
  {"id": "4.1-basic-01", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.A.1", "prompt": "A developer writes the following class to manage members of a fitness club.\npublic class MembershipCard\n{\n    public String memberID;\n    private String homeAddress;\n    public String lookupAddress(String id)\n    {\n        if (id.equals(memberID))\n        {\n            return homeAddress;\n        }\n        else\n        {\n            return \"No match found\";\n        }\n    }\n}\nWhat is the greatest personal privacy risk posed by this class design?", "choices": ["The class contains no constructor shown in the code segment", "The lookupAddress method compares Strings using the equals method instead of ==", "memberID has public visibility, so outside code can read it directly and pass it to lookupAddress to retrieve a member's private home address", "homeAddress is declared private, preventing the class from being reused"], "answer": 2, "explanation": "Because memberID is public, any code holding a MembershipCard object can access its memberID field directly and then supply that same value to lookupAddress to obtain the private homeAddress (4.1.A.1). The missing constructor and the comparison method used create no privacy risk, and declaring homeAddress private is actually the correct choice, not a flaw \u2014 the risk comes entirely from memberID's public visibility."},
  {"id": "4.1-basic-02", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.A.1", "prompt": "A fitness-tracking app asks users to create an account and begin recording their heart rate during workouts. Users are never told that their heart-rate data will later be sold to advertising companies. Which of the following best identifies the ethical concern raised by this practice?", "choices": ["Users were not informed about how their personal data would be used, which violates the principle of informed consent", "The app measures heart rate using a hardware sensor instead of user input", "The heart-rate data is stored using a private instance variable", "The app requires users to create a password before recording data"], "answer": 0, "explanation": "Safeguarding personal privacy requires that users understand how their data will be used; selling heart-rate data without disclosure violates informed consent (4.1.A.1). How the data is measured, that it is properly stored as private, and password requirements are unrelated details that do not address the actual ethical problem."},
  {"id": "4.1-basic-03", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.B.1", "prompt": "Which of the following best describes what is meant by algorithmic bias?", "choices": ["A program that takes longer than expected to run on very large inputs", "A systemic and repeated pattern in a program's outputs that produces unfair outcomes for a specific group of users", "A single incorrect value that was mistakenly entered into a data set", "A program that stops running unexpectedly when given invalid input"], "answer": 1, "explanation": "Algorithmic bias refers to systemic and repeated errors that create unfair outcomes for a specific group of users (4.1.B.1). A slow-running program describes an efficiency issue, one incorrect data value describes a data-quality issue rather than a systemic pattern, and a program crashing describes an error-handling issue \u2014 none of these match the definition of bias."},
  {"id": "4.1-basic-04", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.B.2", "prompt": "An app developer wants to know whether teenagers generally prefer a new messaging feature. The developer posts a poll only on their own personal social media account and uses only the responses from people who choose to reply. Which of the following is the greatest concern before drawing conclusions from these results?", "choices": ["The poll used a written survey instead of a spoken interview", "The poll was conducted using a mobile application", "The results were rounded to the nearest whole percent", "Only the developer's own followers, a self-selected group, chose to respond, so the results may not represent teenagers in general"], "answer": 3, "explanation": "Relying on a voluntary sample drawn only from one person's followers introduces self-selection bias, so the results may not generalize to teenagers as a whole (4.1.B.2). The survey format, application platform, and rounding of results have no meaningful effect on whether the sample is representative."},
  {"id": "4.1-basic-05", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.B.3", "prompt": "A school scheduling program uses a course-enrollment data set to automatically assign class periods. A data-entry error caused the student ID field to be left blank for several dozen enrollment records. If the program uses this data set as-is, what is the most likely consequence?", "choices": ["The program may fail to correctly schedule the students whose enrollment records are missing a student ID", "The program will automatically detect and correct the missing student IDs before running", "The blank student ID fields will cause the program to run faster, since less data needs to be processed", "The missing student IDs will have no effect, since scheduling depends only on course names"], "answer": 0, "explanation": "A data set with missing or inaccurate values, like blank student ID fields, can cause a program to work incorrectly for the affected records (4.1.B.3). Programs do not automatically detect and repair bad data, missing fields do not improve performance, and scheduling in this scenario depends on matching each record to a specific student, which the missing IDs prevent."},
  {"id": "4.1-basic-06", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.C.1", "prompt": "A library's data set records, for each book, its title, genre, and every date it was checked out. A librarian wants to determine which books in the collection are the most physically damaged. Can this be determined using only the library's data set?", "choices": ["Yes, damage can be calculated using the genre field", "Yes, damage can be calculated using the checkout-date field", "No, the data set contains no information describing a book's physical condition", "Yes, but only for books that have been checked out more than five times"], "answer": 2, "explanation": "The data set only tracks title, genre, and checkout dates, none of which describe physical condition, so it cannot be used to determine damage (4.1.C.1). Genre and checkout dates are unrelated to a book's physical state, and checkout frequency alone does not indicate damage either."},
  {"id": "4.1-basic-07", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.B.3", "prompt": "A weather app maintains a historical rainfall data set for a city. Because of a hardware limitation, the automated rain sensor fails to log any reading whenever a storm is severe enough to knock out its power supply, so entries for the heaviest storm days are frequently missing entirely. If the app uses this data set as-is to calculate each month's average rainfall, what is the most likely problem?", "choices": ["Because the missing entries disproportionately occur during heavy storms, the computed monthly averages are likely to underestimate actual rainfall", "The data set will automatically substitute the correct rainfall value for each missing entry", "The missing entries only affect the single day on which they occurred and nothing else", "The app's calculations will become more accurate the longer the missing data goes uncorrected"], "answer": 0, "explanation": "Because the missing readings are concentrated on the heaviest storm days rather than spread randomly, using the incomplete data set as-is causes the computed average to be systematically skewed toward underestimating rainfall (4.1.B.3). Data sets do not self-correct missing values, an average calculated across many days is affected by which specific days are missing rather than being isolated to one day, and the passage of time does not fix an underlying data-collection flaw."},
  {"id": "4.1-basic-08", "course": "csa", "topic": "4.1", "tier": "basic", "lo": "4.1.B.1", "prompt": "A company builds a resume-screening program trained almost entirely on resumes previously submitted from applicants in one industry. After release, the program consistently ranks equally qualified applicants from other industries lower than applicants from the industry it was trained on. What does this scenario best illustrate?", "choices": ["A logic error caused by an incorrect loop condition in the ranking method", "Algorithmic bias, since the program produces systematically unfair outcomes for applicants from underrepresented industries", "A licensing violation caused by using resumes without permission", "A missing return statement in the program's ranking method"], "answer": 1, "explanation": "A program that repeatedly produces unfair outcomes for a specific group, here applicants from underrepresented industries, is a textbook example of algorithmic bias (4.1.B.1). Nothing in the scenario describes a loop condition, a licensing issue, or a missing return statement \u2014 the problem is rooted in unrepresentative training data, not a coding error."},
  {"id": "4.1-intermediate-01", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.A.1", "prompt": "Two students each design a class to represent a registered voter.\nDesign VoterA:\npublic class VoterA\n{\n    public String voterIDNumber;\n    private String votingHistory;\n    public String getHistory(String id)\n    {\n        if (id.equals(voterIDNumber))\n        {\n            return votingHistory;\n        }\n        else\n        {\n            return \"Access denied\";\n        }\n    }\n}\nDesign VoterB:\npublic class VoterB\n{\n    private String voterIDNumber;\n    private String votingHistory;\n    public String getHistory(String id)\n    {\n        if (id.equals(voterIDNumber))\n        {\n            return votingHistory;\n        }\n        else\n        {\n            return \"Access denied\";\n        }\n    }\n}\nWhich design poses a greater privacy risk, and why?", "choices": ["VoterB, because it declares a getHistory method", "VoterA, because voterIDNumber is public, so outside code can read it directly and supply it to getHistory to retrieve private voting history", "Both designs pose identical risk, since both classes include a getHistory method", "VoterB, because it declares more private instance variables than VoterA"], "answer": 1, "explanation": "In VoterA, voterIDNumber has public visibility, so any outside code can read its value directly from an object and then pass that same value into getHistory to obtain the private votingHistory; VoterB avoids this because voterIDNumber is private (4.1.A.1). Both classes have identical getHistory methods, so the method itself is not what creates the risk, and the number of private variables is unrelated to the actual privacy exposure."},
  {"id": "4.1-intermediate-02", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.B.2", "prompt": "A school wants to measure how satisfied students are with the cafeteria menu. Method 1: randomly select 200 students from the full enrollment list and require each selected student to complete a brief survey during homeroom. Method 2: leave a stack of paper surveys on a cafeteria table for students to complete voluntarily if they choose. Which method is more likely to produce a representative sample of the student body, and why?", "choices": ["Method 2, because paper surveys are inherently more accurate than digital ones", "Method 2, because only the most motivated students will take the time to respond thoughtfully", "Both methods are equally representative, since both are technically surveys", "Method 1, because randomly selecting from the full enrollment list avoids the self-selection bias present when students choose whether to participate"], "answer": 3, "explanation": "Randomly selecting from the entire enrollment list, as in Method 1, ensures every student has an equal chance of being included, avoiding the self-selection bias created when only motivated students opt in, as in Method 2 (4.1.B.2). Paper versus digital format has no bearing on representativeness, and greater motivation to respond does not make a voluntary sample representative of the whole student body."},
  {"id": "4.1-intermediate-03", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.B.3", "prompt": "A food-delivery app logs the delivery time for every order in a city-wide data set. Due to a sensor glitch, about 5% of entries record a delivery time of exactly 0 minutes whenever the driver's phone briefly loses GPS signal mid-delivery. A team wants to compute the citywide average delivery time using every row in the data set as-is. Which statement best evaluates this plan?", "choices": ["The zero-minute entries are inaccurate and should be identified and corrected or excluded, or the computed average will be understated", "The zero-minute entries should be included exactly as recorded, since they represent deliveries that were genuinely completed instantly", "The data set is entirely unusable, and no meaningful statistic can be computed from it", "The zero-minute entries indicate that the delivery-assignment algorithm is biased against certain neighborhoods"], "answer": 0, "explanation": "A delivery time of 0 minutes is not a real delivery duration but the result of a sensor error, so these inaccurate entries should be corrected or excluded before computing an average, or the result will be skewed lower than reality (4.1.B.3). It is not reasonable to treat 0 minutes as a real value, the rest of the data set is still usable once these entries are addressed, and nothing in the scenario points to bias in an assignment algorithm."},
  {"id": "4.1-intermediate-04", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.C.1", "prompt": "A city's public data set of bike-share trips includes, for each trip, the start station, end station, trip duration, and bike ID. A city planner wants to determine the average household income of people who use the bike-share program. Which statement best evaluates whether this can be done using only the bike-share data set?", "choices": ["Income level can be estimated directly using the bike ID field", "Income level can be estimated directly using the trip duration field", "Income level cannot be determined, since the data set contains no demographic or financial information about riders", "Income level can be estimated by combining the start station and end station fields"], "answer": 2, "explanation": "The bike-share data set only records trip-related information \u2014 stations, duration, and bike ID \u2014 and includes nothing about who the riders are financially, so income cannot be extrapolated from it (4.1.C.1). Bike ID, trip duration, and station combinations describe trips, not riders' financial circumstances, so none of them can substitute for the missing demographic data."},
  {"id": "4.1-intermediate-05", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.B.1", "prompt": "A bank's loan-approval program is trained on decades of historical loan decisions. In the past, the bank approved loans at a noticeably lower rate for applicants living in certain zip codes, regardless of income or credit history. The new program, trained on this history, continues to approve applicants from those zip codes at a lower rate. Which best explains why this is considered algorithmic bias?", "choices": ["The program takes longer to process applications from those zip codes than from others", "The program was released without first being tested on any sample loan applications", "The program stores each applicant's zip code using a public instance variable", "The program perpetuates a historical pattern, producing systematically less favorable outcomes for applicants from those zip codes regardless of their individual qualifications"], "answer": 3, "explanation": "Because the program was trained on biased historical data, it reproduces a systematic pattern of unfavorable outcomes for a specific group of applicants, which is exactly what algorithmic bias means (4.1.B.1). Processing speed, whether testing occurred, and how zip code is stored in the class (public or private) are unrelated to why the outcomes themselves are biased."},
  {"id": "4.1-intermediate-06", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.A.1", "prompt": "A sleep-tracking app discloses, deep within a lengthy terms-of-service document that almost no users actually read, that anonymized sleep data will be shared with third-party advertisers. Which of the following would best address the ethical concern raised by this practice?", "choices": ["Encrypting the sleep data before it is transmitted to advertisers", "Presenting the disclosure clearly and prominently rather than burying it in a lengthy document users are unlikely to read", "Rewriting the sleep-tracking algorithm so that it runs more efficiently", "Declaring the instance variables that store sleep data as public instead of private"], "answer": 1, "explanation": "Safeguarding personal privacy means users must be meaningfully informed, not merely technically informed, about how their data is used, so making the disclosure clear and prominent directly addresses the informed-consent problem (4.1.A.1). Encrypting the data in transit and improving algorithm efficiency do not address whether users understood the disclosure, and making the fields public would make the privacy problem worse, not better."},
  {"id": "4.1-intermediate-07", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.B.2", "prompt": "A company wants to determine the average battery life of a new phone model across its entire customer base. To measure this, the company tests only 5 phones, all used daily by employees in its own engineering department. Which of the following is the primary issue with this approach?", "choices": ["The sample is small and drawn only from employees, who may use the phone differently than typical customers, so the results may not generalize to the customer base", "Employees are more likely to answer survey questions dishonestly", "Battery life cannot be measured using any objective method", "The company should have tested a completely different phone model instead"], "answer": 0, "explanation": "Testing only 5 phones used exclusively by engineering employees is both a very small sample and one likely to behave differently from typical customers, so the results may not represent the broader customer base (4.1.B.2). This scenario does not involve a survey or dishonest answers, battery life is an objectively measurable quantity, and the issue is with who was sampled, not which phone model was tested."},
  {"id": "4.1-intermediate-08", "course": "csa", "topic": "4.1", "tier": "intermediate", "lo": "4.1.C.1", "prompt": "A city team wants to determine how weather conditions affect daily park attendance. Data set 1 contains, for each date and park, the number of visitors. Data set 2 contains, for each date, the temperature and amount of precipitation. Data set 3 contains, for each park, its name and size in acres. Which data sets, combined, would let the team determine how weather affects park attendance?", "choices": ["Data sets 1 and 3", "Data sets 1 and 2", "Data sets 2 and 3", "Data set 3 alone"], "answer": 1, "explanation": "Data set 1 provides attendance by date and park, and data set 2 provides weather conditions by date, so matching them by date lets the team analyze how weather relates to attendance (4.1.C.1). Data set 3 describes park size, which has no bearing on weather, so pairing it with either other data set does not answer the question, and no single data set alone contains both attendance and weather information."},
  {"id": "4.1-complex-01", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.A.1", "prompt": "Consider the following class used by a company to manage employee records.\npublic class EmployeeDirectory\n{\n    public String badgeNumber;\n    private String salary;\n    private String homeAddress;\n    public String getSalary(String badge)\n    {\n        if (badge.equals(badgeNumber))\n        {\n            return salary;\n        }\n        else\n        {\n            return \"Access denied\";\n        }\n    }\n    public String getHomeAddress(String badge)\n    {\n        if (badge.equals(badgeNumber))\n        {\n            return homeAddress;\n        }\n        else\n        {\n            return \"Access denied\";\n        }\n    }\n}\nConsider the following statements about this class design.\nI. Because badgeNumber is public, any outside code that has access to an EmployeeDirectory object can read that employee's badge number directly.\nII. Because badgeNumber is public, any outside code that reads it can pass it into getSalary or getHomeAddress to retrieve that employee's private salary or home address.\nIII. Declaring salary and homeAddress as private fully protects them, regardless of what other fields in the class are public.\nIV. If badgeNumber were declared private instead, outside classes that do not otherwise already know an employee's badge number could no longer use it to retrieve that employee's salary or home address.\nWhich of the following identifies all the true statements?", "choices": ["I and II only", "I, II, and IV only", "II and III only", "I, II, III, and IV"], "answer": 1, "explanation": "Statements I and II correctly describe how a public badgeNumber field lets outside code read it directly and use it to unlock private data through the accessor methods, and statement IV is also true because making badgeNumber private removes that avenue for any outside class that does not already possess the badge number some other way (4.1.A.1). Statement III is false: declaring salary and homeAddress private does not fully protect them, since the public badgeNumber field still allows their values to be extracted through the class's own methods."},
  {"id": "4.1-complex-02", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.B.2", "prompt": "A city wants to measure overall resident satisfaction with its public bus system. The transit department posts a QR-code link to a survey, written only in English, on posters placed inside city buses. Consider the following statements about this data-collection approach.\nI. Because only riders who notice the poster and own a smartphone can respond, results may overrepresent riders who are engaged and motivated enough to complete a survey, rather than all bus riders.\nII. Residents who never ride the bus at all have no chance of being included, so the survey cannot explain why non-riders avoid the bus.\nIII. Because the eventual sample size is larger than 1,000 responses, sampling bias introduced by how respondents were recruited is no longer a concern.\nIV. Posting the survey only in English restricts the sample to riders who read English, potentially excluding the opinions of non-English-speaking riders.\nWhich of the following identifies all the true statements?", "choices": ["I, II, and IV only", "I and III only", "II and IV only", "I, II, III, and IV"], "answer": 0, "explanation": "Statements I, II, and IV correctly identify real sources of sampling bias: only certain riders can see and access the poster, non-riders are entirely excluded, and the English-only survey excludes non-English-speaking riders (4.1.B.2). Statement III is false because a large total sample size does not eliminate bias introduced by how participants were recruited; a large but unrepresentative sample is still unrepresentative."},
  {"id": "4.1-complex-03", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.B.3", "prompt": "A hospital keeps a data set logging, for every visit in the past year, the time each patient checked in and the time they were first seen by a doctor. An audit reveals that the front-desk check-in software regularly crashed during overnight shifts, so staff wrote check-in times on paper and entered them into the system later, sometimes introducing typos, such as accidentally logging 11:15 PM as 1:15 AM. Consider the following statements.\nI. Because check-in times are missing for some overnight visits, computing an average wait time using only the complete records will systematically leave out overnight-shift experiences.\nII. The typos introduced during manual re-entry could cause the program to compute nonsensical wait times, such as a negative number of minutes, for the affected visits.\nIII. Because the data set spans a full year, none of the missing or incorrect entries meaningfully affects any statistic computed from it.\nIV. Using this data set as-is to compare average wait times across different shifts could lead to inaccurate or misleading conclusions.\nWhich of the following identifies all the true statements?", "choices": ["I and IV only", "II and III only", "I, II, and IV only", "I, II, III, and IV"], "answer": 2, "explanation": "Statements I, II, and IV are true: missing overnight records skew any average that excludes them, entry typos can produce nonsensical computed wait times, and both problems together make shift comparisons unreliable (4.1.B.3). Statement III is false because the size of the overall data set does not protect against systematic errors that are concentrated in a specific subset, such as overnight visits, rather than spread randomly throughout the year."},
  {"id": "4.1-complex-04", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.C.1", "prompt": "A school's data set contains, for each student, a student ID, GPA, number of extracurricular clubs joined, and assigned lunch period. An administrator wants to investigate several separate questions using only this data set.\nI. Whether students who join more extracurricular clubs tend to have higher GPAs.\nII. Whether students are satisfied with the school's new cafeteria menu.\nIII. Whether the number of clubs a student joins is related to which lunch period they are assigned.\nIV. Whether students who join clubs are more likely to attend a four-year college after graduation.\nFor which of these questions can the data set actually be used to draw a conclusion?", "choices": ["I, II, and III only", "II, III, and IV only", "I and III only", "I, II, III, and IV"], "answer": 2, "explanation": "The data set includes GPA, club count, and lunch period, so question I (clubs versus GPA) and question III (clubs versus lunch period) can both be investigated directly using fields already present (4.1.C.1). Question II cannot be investigated because the data set contains no information about cafeteria-menu opinions, and question IV cannot be investigated because the data set contains no information about college attendance after graduation."},
  {"id": "4.1-complex-05", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.B.1", "prompt": "A voice-assistant program for smartphones is trained primarily on speech recordings from adult speakers with one regional accent. After release, users report that the assistant frequently misunderstands commands from children and from speakers with different regional accents. Consider the following statements.\nI. This outcome is an example of algorithmic bias, since the program produces systematically worse results for identifiable groups of users.\nII. Retraining the program using a much more diverse and representative set of voice recordings would likely help reduce this bias.\nIII. Because the program was not intentionally designed to disadvantage any group, its unequal performance does not count as algorithmic bias.\nIV. The unequal performance described is entirely unrelated to how the training data was originally collected.\nWhich of the following identifies all the true statements?", "choices": ["I, III, and IV only", "II and III only", "III and IV only", "I and II only"], "answer": 3, "explanation": "Statements I and II are true: producing systematically worse results for children and for speakers with different accents is exactly what algorithmic bias means, and training on a more diverse, representative data set is a standard way to reduce such bias (4.1.B.1, 4.1.B.2). Statement III is false because intent is irrelevant to whether bias exists \u2014 bias is defined by the pattern of unfair outcomes, not the programmer's intentions \u2014 and statement IV is false because the unequal performance is directly caused by how narrow and unrepresentative the training recordings were."},
  {"id": "4.1-complex-06", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.B.2", "prompt": "A university research team wants to study study habits across the entire student body. To recruit participants, the team invites only students who already follow the research lab's Instagram account. As part of the survey, the team also asks each participant to submit their unencrypted student ID number, explained as being collected \"in case we want to follow up,\" and these ID numbers are stored in a spreadsheet viewable by all of the lab's undergraduate volunteers. Consider the following statements.\nI. Recruiting only Instagram followers introduces sampling bias, since the sample likely overrepresents students who already engage with the lab's social media rather than the broader student population.\nII. Collecting unencrypted student ID numbers, viewable by many undergraduate volunteers, raises a personal-privacy concern beyond what the study requires.\nIII. Because the study is being conducted by a university research team, sampling bias and privacy concerns do not apply.\nIV. Both problems could be reduced: sampling could use a randomized invitation sent to the entire student body, and ID numbers could be stored securely and accessed only by essential personnel.\nWhich of the following identifies all the true statements?", "choices": ["I and III only", "II and IV only", "I, II, and IV only", "I, II, III, and IV"], "answer": 2, "explanation": "Statements I, II, and IV are all true: recruiting only from existing followers biases the sample toward already-engaged students, storing unencrypted IDs visibly is an unnecessary privacy risk, and both problems have practical fixes (4.1.A.1, 4.1.B.2). Statement III is false because being affiliated with a university research team does not exempt a study from concerns about sampling bias or personal privacy."},
  {"id": "4.1-complex-07", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.C.1", "prompt": "A nonprofit wants to determine whether a new after-school tutoring program improves standardized test scores district-wide. It has access to two data sets. Data set 1 contains tutoring-attendance records (student ID and number of sessions attended) for only the 3 schools in the district that adopted the program. Data set 2 contains standardized test scores (student ID and score) for all schools in the district, but 15% of the student ID entries are missing because of a syncing error between two record systems. Consider the following statements.\nI. Because data set 1 only includes the 3 schools that adopted the program, any conclusions drawn should be limited to those schools rather than generalized to the entire district.\nII. The missing 15% of student IDs in data set 2 could bias results if the missing records are not spread randomly, for example if they disproportionately belong to one particular school.\nIII. Combining data sets 1 and 2 by matching student ID is, by itself, sufficient to prove that tutoring attendance caused any change in test scores.\nIV. Even after combining the data sets, the nonprofit should consider whether other differences between the 3 adopting schools and the rest of the district might explain any observed differences in scores.\nWhich of the following identifies all the true statements?", "choices": ["II and III only", "I and IV only", "I, II, and III only", "I, II, and IV only"], "answer": 3, "explanation": "Statements I, II, and IV are true: conclusions from a 3-school data set should not be generalized district-wide, non-randomly missing IDs can bias results, and other differences between schools could still explain observed score differences even after combining data sets (4.1.C.1, 4.1.B.3). Statement III is false because matching records by student ID only allows the two variables to be compared side by side \u2014 it does not, by itself, establish that tutoring attendance caused any change in scores."},
  {"id": "4.1-complex-08", "course": "csa", "topic": "4.1", "tier": "complex", "lo": "4.1.A.1", "prompt": "A mental-health journaling app uses the following class to store entries.\npublic class JournalEntry\n{\n    public String username;\n    private String entryText;\n    private boolean flaggedUrgent;\n    public String getEntryText(String user)\n    {\n        if (user.equals(username))\n        {\n            return entryText;\n        }\n        else\n        {\n            return \"Access denied\";\n        }\n    }\n}\nThe app's published privacy policy states that entries \"may be reviewed by licensed counselors,\" but does not mention that anonymized excerpts of entryText are also used to train a separate, publicly available marketing chatbot. Consider the following statements.\nI. Because username is declared public, other code in the program can read a JournalEntry object's username directly, without calling any method.\nII. Any code that already knows a user's username could call getEntryText with that username to retrieve that user's private journal entry text.\nIII. Using anonymized excerpts to train a marketing chatbot, which was not disclosed in the privacy policy, raises an informed-consent concern separate from the public username field.\nIV. Because entryText and flaggedUrgent are declared private, this class design poses no privacy risk of any kind.\nWhich of the following identifies all the true statements?", "choices": ["I and IV only", "II and IV only", "III and IV only", "I, II, and III only"], "answer": 3, "explanation": "Statements I, II, and III are all true: a public username field can be read directly by outside code and used to retrieve private entryText through getEntryText, and separately, using excerpts to train a chatbot without disclosing that use raises its own informed-consent problem (4.1.A.1). Statement IV is false because declaring entryText and flaggedUrgent private does not eliminate all privacy risk in this design \u2014 the public username field still creates a path to the private entryText through the class's own method."},
  {"id": "4.2-basic-01", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.1", "prompt": "Which of the following best describes what a data set is?", "choices": ["A single value stored in one variable", "A collection of specific pieces of information that can be examined and analyzed together", "A method that performs a calculation without using any input", "A diagram that has no data associated with it"], "answer": 1, "explanation": "A data set is a collection of specific pieces of information or data (4.2.A.1). A single stored value is just one data point, not a collection; a parameterless method describes a procedure, not stored information; and a diagram with no underlying data is not a data set at all."},
  {"id": "4.2-basic-02", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.2", "prompt": "A programmer wants to find the total number of orders placed on a Friday from a large data set of restaurant orders. Which best describes how the data set would typically be analyzed to answer this question?", "choices": ["Every order in the data set is accessed one at a time, and orders placed on a Friday are counted", "The entire data set is deleted so the answer can be entered manually", "Only the very first order in the data set is examined", "The data set is converted into a single number before any individual orders are examined"], "answer": 0, "explanation": "When analyzing a data set, values are accessed and processed one at a time according to the desired outcome, in this case checking each order's date and counting the Fridays (4.2.A.2). Deleting the data set would destroy the information needed, examining only the first order ignores nearly all the data, and a data set cannot be meaningfully condensed to one number before it is examined."},
  {"id": "4.2-basic-03", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.3", "prompt": "Before writing an algorithm to find the highest-scoring student on a class quiz, a teacher first organizes the scores into a table with one row per student and columns for studentName and quizScore. What is the primary benefit of creating this table first?", "choices": ["It automatically calculates the highest score without any further work", "It permanently removes the need to look at the raw data ever again", "It provides a visual representation of the data that helps in planning how the algorithm will access and compare the values", "It guarantees that none of the scores contain errors"], "answer": 2, "explanation": "Representing data in a table helps plan the algorithm that will manipulate the data, in this case by making it easier to see how each student's score will need to be accessed and compared (4.2.A.3). The table itself performs no calculation, does not eliminate the need to reference the data later, and organizing data cannot guarantee the data is error-free."},
  {"id": "4.2-basic-04", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.1", "prompt": "A library's data set includes the following columns for each checkout event: bookTitle, borrowerID, checkoutDate. Which question could be answered using only this data set?", "choices": ["How much did the library pay to purchase each book?", "Which books have the best average customer rating?", "Which borrower owes the most money in overdue fines?", "Which borrower checked out the greatest number of books?"], "answer": 3, "explanation": "Since the data set is a collection of specific pieces of information limited to bookTitle, borrowerID, and checkoutDate, only questions answerable from those exact columns can be resolved, and counting checkoutDate entries per borrowerID reveals who checked out the most books (4.2.A.1). Purchase cost, customer ratings, and overdue fines all require columns, such as price, rating, or return date, that are not part of this data set."},
  {"id": "4.2-basic-05", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.2", "prompt": "A food truck's data set includes the columns itemName, unitPrice, and quantitySoldToday for each menu item. Which question can be answered using only this data set?", "choices": ["Which item received the highest customer satisfaction rating?", "Which item generated the most total revenue today?", "Which supplier provided the ingredients for each item?", "How many calories does each item contain?"], "answer": 1, "explanation": "Multiplying unitPrice by quantitySoldToday for each item and comparing the results is a straightforward way to process this data set's values and answer the question of which item generated the most revenue (4.2.A.2). Customer satisfaction, supplier information, and calorie counts all require data that is not part of this data set."},
  {"id": "4.2-basic-06", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.1", "prompt": "A weather app stores the date, high temperature, and low temperature for every day of the past year. This collection of information is best described as...", "choices": ["a single behavior performed by the app", "a method that returns exactly one value", "a data set, since it is a collection of specific pieces of information", "a class variable shared by every user of the app"], "answer": 2, "explanation": "A year's worth of dates and temperatures recorded together is exactly what is meant by a data set: a collection of specific pieces of information (4.2.A.1). It is not a single behavior or method, since no action or calculation is described, and it is not a class variable, which refers to one shared piece of data rather than a whole collection of records."},
  {"id": "4.2-basic-07", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.3", "prompt": "A gym manager wants to write an algorithm that finds the member who attended the most classes this month. Before writing any code, the manager arranges the data into a table with one row per member and columns for memberName and classesAttended. What is the most important reason for creating this table first?", "choices": ["It visually organizes the data so the manager can plan how the algorithm will compare the classesAttended values", "It permanently stores the data so it never needs to be updated again", "It automatically sorts the members alphabetically by name", "It eliminates the need for the algorithm to examine every member's row"], "answer": 0, "explanation": "Representing the data as a table lets the manager see the structure of the data and plan how the algorithm will need to access and compare each member's classesAttended value (4.2.A.3). The table does not update automatically over time, does not sort anything by itself, and the algorithm will still need to examine every row to find the maximum."},
  {"id": "4.2-basic-08", "course": "csa", "topic": "4.2", "tier": "basic", "lo": "4.2.A.2", "prompt": "An app store's data set includes the columns appName, reviewDate, and starRating (1 to 5) for each review submitted. Which question can be answered using only this data set?", "choices": ["How many times has each app been downloaded?", "What is the price of each app?", "Who developed each app?", "Which app has the highest average star rating?"], "answer": 3, "explanation": "Grouping the starRating values by appName and computing an average for each app is a direct way to process this data set to answer the question (4.2.A.2). Download counts, price, and developer information all require columns that are not present in this data set."},
  {"id": "4.2-intermediate-01", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A hospital emergency room keeps a data set with the following columns for each visit: patientID, arrivalTime, departureTime, triageLevel (1-5), and insuranceProvider. Which of the following cannot be determined using only the information in this data set?", "choices": ["The percentage of the hospital's total ER beds that were occupied at any given time", "The average amount of time patients spent in the ER", "The most common triage level among patients", "The most common insurance provider among patients"], "answer": 0, "explanation": "Determining bed occupancy percentage requires knowing the hospital's total number of ER beds, a value that is not one of the data set's columns, so it cannot be determined (4.2.A.2). Average time in the ER can be computed from departureTime minus arrivalTime, and the most common triage level or insurance provider can both be found by counting occurrences of values already present in the data set."},
  {"id": "4.2-intermediate-02", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A sports analyst wants to compare points scored by position in home games versus away games. The analyst has access to the following data sets.\nData set 1 contains playerID and position for each player.\nData set 2 contains playerID, gameID, pointsScored, and homeOrAway for each game a player participated in.\nData set 3 contains gameID and attendance for each game.\nData set 4 contains playerID and teamSalary for each player.\nWhich two data sets, combined, allow the analyst to answer this question?", "choices": ["Data sets 1 and 4", "Data sets 1 and 2", "Data sets 3 and 4", "Data sets 2 and 3"], "answer": 1, "explanation": "Data set 1 provides each player's position, and Data set 2 provides each player's points scored along with whether the game was home or away, so combining them by playerID allows points to be compared by position and home/away status (4.2.A.2). Data sets 3 and 4 contain attendance and salary information, which are irrelevant to the question and do not help link position to scoring performance."},
  {"id": "4.2-intermediate-03", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A school's data set includes the following columns for each of its clubs: clubName, numberOfMembers, numberOfMeetingsHeld, and percentAttendanceAtLastMeeting. Which of the following cannot be determined using only the information in this data set?", "choices": ["The club with the greatest number of members", "The club with the highest percent attendance at its most recent meeting", "The total number of students in the school who do not belong to any club", "The average number of meetings held across all clubs"], "answer": 2, "explanation": "Determining how many students belong to no club at all would require knowing the school's total student enrollment, which is not one of the data set's columns, so it cannot be determined (4.2.A.2). The club with the most members, the club with the highest recent attendance percentage, and the average number of meetings held can all be computed directly from the columns shown."},
  {"id": "4.2-intermediate-04", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.3", "prompt": "A student is comparing daily high temperatures for City A and City B over one week, organized in the following table.\nDay   CityA_High   CityB_High\nMon   78           82\nTue   81           79\nWed   85           88\nThu   90           84\nFri   88           91\nThe student wants to design an algorithm to find the day with the largest temperature difference between the two cities. Which change to the table would best help in planning that algorithm?", "choices": ["Removing the Day column entirely", "Sorting the rows alphabetically by day name", "Combining CityA_High and CityB_High into a single column", "Adding a new column that shows the difference between CityA_High and CityB_High for each day"], "answer": 3, "explanation": "Adding a column that already shows each day's temperature difference visually organizes the exact values the algorithm will need to compare, directly supporting the planning of the algorithm (4.2.A.3). Removing the Day column would make it impossible to identify which day is largest, alphabetical sorting does not relate to temperature values at all, and combining the two temperature columns into one would make the individual city values impossible to compare."},
  {"id": "4.2-intermediate-05", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A social media platform's data set includes the columns postID, username, postDate, numLikes, numComments, and numShares for each post. Which of the following can be determined using only this data set?", "choices": ["The post with the highest total number of likes", "The age of the user who created each post", "Whether a post's content violates community guidelines", "The geographic location where each post was viewed"], "answer": 0, "explanation": "Comparing the numLikes values across all posts directly identifies the post with the highest total, since numLikes is a column already present in the data set (4.2.A.2). User age, guideline violations, and viewing location all require information that is not included among the data set's columns."},
  {"id": "4.2-intermediate-06", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A streaming service wants to compare which movie genres are most popular among subscribers under 30 versus subscribers 30 and older. The service has access to the following data sets.\nData set 1 contains subscriberID and age for each subscriber.\nData set 2 contains subscriberID, watchedTitle, and genre for each title watched.\nData set 3 contains movieTitle and criticScore for each movie.\nData set 4 contains subscriberID and subscriptionPlan for each subscriber.\nWhich two data sets, combined, allow the service to answer this question?", "choices": ["Data sets 3 and 4", "Data sets 1 and 2", "Data sets 2 and 4", "Data sets 1 and 3"], "answer": 1, "explanation": "Data set 1 provides each subscriber's age, and Data set 2 provides the genre of every title each subscriber watched, so combining them by subscriberID allows genre popularity to be compared across the two age groups (4.2.A.2). Critic scores and subscription plan type do not provide any information about which genres subscribers watched or their ages, so they do not help answer this question."},
  {"id": "4.2-intermediate-07", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.1", "prompt": "A meteorologist keeps a record with columns for date, temperature, humidity, and windSpeed for every day of a month. A separate report states only the month's single average temperature. Which statement correctly compares these two things?", "choices": ["Both are data sets, since both contain a temperature value", "The average temperature report is a data set, but the daily record is not, because it has more than one column", "The daily record is a data set, since it is a collection of many individual data points, while the single average temperature is just one derived value", "Neither is a data set, because a data set must contain only non-numeric information"], "answer": 2, "explanation": "A data set is a collection of specific pieces of information, which describes the daily record of many days' worth of readings, while a single average temperature is just one computed value, not a collection (4.2.A.1). Containing a temperature value alone does not make something a data set, having multiple columns is not disqualifying, and data sets are not restricted to non-numeric information."},
  {"id": "4.2-intermediate-08", "course": "csa", "topic": "4.2", "tier": "intermediate", "lo": "4.2.A.2", "prompt": "A fitness app's data set includes, for each user over one month, the columns userName, totalStepsWalked, totalWorkoutsLogged, averageSleepHours, and numberOfFriendsOnApp. Which of the following cannot be determined using only the information in this data set?", "choices": ["The user who walked the greatest total number of steps", "The average number of sleep hours across all users", "The user who logged the most workouts", "The user whose heart rate was highest during any single workout"], "answer": 3, "explanation": "Determining a user's heart rate during a workout would require a heart rate column, which is not part of this data set, so it cannot be determined (4.2.A.2). The user with the most steps, the average sleep hours across users, and the user with the most logged workouts can all be found directly from columns already present in the data set."},
  {"id": "4.2-complex-01", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "An online bookstore's data set includes the following columns for each order: orderID, customerID, orderDate, bookGenre, bookPrice, and shippingRegion. Consider the following statements about what can be determined using only this data set.\nI. The total revenue generated by each book genre\nII. The average customer satisfaction rating for each genre\nIII. The shipping region that generates the greatest number of orders\nIV. The publisher of each book ordered\nWhich of the following is a correct evaluation of statements I-IV?", "choices": ["I and III can be determined, but II and IV cannot", "I, II, and III can be determined, but IV cannot", "Only I can be determined", "II and IV can be determined, but I and III cannot"], "answer": 0, "explanation": "Total revenue by genre can be found by summing bookPrice grouped by bookGenre, and the shipping region with the most orders can be found by counting shippingRegion occurrences, since both rely only on columns present in the data set; satisfaction rating and publisher are not columns in the data set, so neither II nor IV can be determined (4.2.A.2). Any option that includes II or IV as determinable, or excludes I or III, misidentifies which columns actually exist in this data set."},
  {"id": "4.2-complex-02", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A college counseling office wants to determine whether students who log more extracurricular hours tend to have higher GPAs. The office has access to the following data sets.\nData set 1 contains studentID, GPA, and intendedMajor for each student.\nData set 2 contains studentID, satScore, and actScore for each student.\nData set 3 contains collegeName, acceptanceRate, and averageGPAofAdmits for each college.\nData set 4 contains studentID and extracurricularHours for each student.\nWhich two data sets, combined, provide the information needed to answer this question?", "choices": ["Data sets 2 and 3", "Data sets 1 and 4", "Data sets 3 and 4", "Data sets 2 and 4"], "answer": 1, "explanation": "Data set 1 provides each student's GPA, and Data set 4 provides each student's extracurricular hours, so combining them by studentID directly allows GPA to be compared against extracurricular involvement (4.2.A.2). Data sets 2 and 3 involve test scores and college-level admissions statistics, neither of which contains the GPA-to-extracurricular-hours link the office actually needs."},
  {"id": "4.2-complex-03", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A hospital's readmission data set includes the following columns for each patient stay: patientID, admissionDate, dischargeDate, diagnosisCode, readmittedWithin30Days, and attendingPhysicianID. Consider the following statements about what can be determined using only this data set.\nI. The number of patients readmitted within 30 days\nII. The average length of stay, computed from admissionDate and dischargeDate\nIII. The physician with the highest patient satisfaction score\nIV. The most common diagnosis code among all stays\nWhich of the following is a correct evaluation of statements I-IV?", "choices": ["I and II only", "I, III, and IV only", "I, II, and IV only", "II, III, and IV only"], "answer": 2, "explanation": "The number of readmissions, the average length of stay, and the most common diagnosis code (I, II, and IV) can all be computed directly from columns already present in the data set, but patient satisfaction score is not one of the data set's columns, so III cannot be determined (4.2.A.2). Any option that includes III, or excludes any of I, II, or IV, misidentifies which columns the data set actually contains."},
  {"id": "4.2-complex-04", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A city planner wants to determine whether bus routes serving lower-income neighborhoods tend to experience longer average delays. The planner has access to the following data sets.\nData set 1 contains busRouteID and dailyRidership for each route.\nData set 2 contains busRouteID and averageDelayMinutes for each route.\nData set 3 contains neighborhoodName and medianHouseholdIncome for each neighborhood.\nData set 4 contains busRouteID and a list of neighborhoodsServed for each route.\nWhich combination of data sets provides everything needed to answer this question?", "choices": ["Data sets 1 and 2", "Data sets 1 and 3", "Data sets 2 and 3", "Data sets 2, 3, and 4"], "answer": 3, "explanation": "Data set 2 provides each route's average delay, Data set 3 provides each neighborhood's income level, and Data set 4 is the necessary link that maps each route to the neighborhoods it serves, so all three together connect delay to neighborhood income (4.2.A.2). Data sets 2 and 3 alone share no common column to connect a route directly to a neighborhood's income, and Data set 1's ridership figures are not needed to answer this particular question."},
  {"id": "4.2-complex-05", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A video game studio's data set includes the columns playerID, sessionDate, sessionDurationMinutes, levelReached, inGamePurchaseAmount, and deviceType for each play session. Consider the following statements about what can be determined using only this data set.\nI. The total amount spent on in-game purchases by all players combined\nII. The average session duration across all players\nIII. The real-world age of each player\nIV. The device type used most often among players who reached the highest level\nWhich of the following is a correct evaluation of statements I-IV?", "choices": ["I, II, and IV only", "I and II only", "I, III, and IV only", "III only"], "answer": 0, "explanation": "Total purchase amount, average session duration, and the most common device type among top-level players (I, II, and IV) can all be computed directly from columns already present in the data set, but player age is not one of the data set's columns, so III cannot be determined (4.2.A.2). Any option that includes III, or that excludes I, II, or IV, misidentifies what this data set actually records."},
  {"id": "4.2-complex-06", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A restaurant chain wants to determine which menu item generates the greatest total profit (revenue minus ingredient cost) at each location. The chain has access to the following data sets.\nData set 1 contains menuItemID and ingredientCost for each item.\nData set 2 contains menuItemID, locationID, and unitsSoldPerMonth for each item at each location.\nData set 3 contains locationID and monthlyRent for each location.\nData set 4 contains menuItemID and customerReviewScore for each item.\nIn addition to each menu item's price, which two data sets together provide the information needed?", "choices": ["Data sets 3 and 4", "Data sets 1 and 2", "Data sets 2 and 3", "Data sets 2 and 4"], "answer": 1, "explanation": "Data set 1 provides each item's ingredient cost, and Data set 2 provides how many units of each item were sold at each location, so combining them by menuItemID allows total profit per item per location to be calculated alongside the item's price (4.2.A.2). Monthly rent and customer review scores do not factor into ingredient-cost-based profit and are not needed to answer this question."},
  {"id": "4.2-complex-07", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.3", "prompt": "A warehouse's data set includes, for each product, the columns productID, category, unitsInStock, reorderThreshold, and weeklyUnitsSold. A manager wants to design an algorithm that flags any product expected to drop below its reorderThreshold within the next two weeks, based on its current weeklyUnitsSold rate. Consider the following possible changes to how the data is organized before writing the algorithm.\nI. Sorting the rows by category alphabetically\nII. Adding a column showing (unitsInStock - 2 x weeklyUnitsSold) for each product\nIII. Removing the productID column since it is not numeric\nIV. Adding a column showing whether (unitsInStock - 2 x weeklyUnitsSold) is less than reorderThreshold\nWhich of these changes would actually help in planning the reorder-flagging algorithm?", "choices": ["I and III only", "I only", "II and IV only", "III and IV only"], "answer": 2, "explanation": "Adding a column that projects stock two weeks out and a column that directly flags whether that projection falls below the threshold (II and IV) both organize the data in a way that visually plans exactly what the algorithm needs to check for each row (4.2.A.3). Alphabetical sorting by category does not help identify which products need reordering, and removing productID would make it impossible to know which specific product was flagged."},
  {"id": "4.2-complex-08", "course": "csa", "topic": "4.2", "tier": "complex", "lo": "4.2.A.2", "prompt": "A team of park researchers wants to determine whether parks with higher monthly visitor counts tend to have fewer wildlife sightings per trail. The team has access to the following data sets.\nData set 1 contains parkID and monthlyVisitorCount for each park.\nData set 2 contains trailID and parkID, mapping each trail to the park that contains it.\nData set 3 contains trailID, sightingDate, and animalSpecies for each recorded wildlife sighting.\nData set 4 contains animalSpecies and conservationStatus for each species.\nWhich combination of data sets provides everything needed to answer this question?", "choices": ["Data sets 1 and 4", "Data sets 3 and 4", "Data sets 1 and 3", "Data sets 1, 2, and 3"], "answer": 3, "explanation": "Data set 1 provides each park's visitor count, Data set 3 provides sighting counts per trail, and Data set 2 is the necessary link that maps each trail to its park, so all three together connect visitor counts to sightings by park (4.2.A.2). Data sets 1 and 3 alone share no common column to connect a park directly to its trails' sightings, and Data set 4's conservation status information is irrelevant to this particular question."},
  {"id": "4.3-basic-01", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.2", "prompt": "An array named tempReadings is created to store temperature readings. Which expression correctly returns the number of elements the array can hold?", "choices": ["tempReadings.length", "tempReadings.length()", "tempReadings.size()", "tempReadings.size"], "answer": 0, "explanation": "An array's length is accessed through the length attribute, without parentheses, since it is not a method call (4.3.A.2). Writing length() incorrectly treats it as a method, and size() or size are used for other collection types, not arrays."},
  {"id": "4.3-basic-02", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.3", "prompt": "int[] scoreCounts = new int[6];\nImmediately after this statement executes, what is the value of scoreCounts[3]?", "choices": ["It is undefined until a value is assigned", "0", "-1", "It causes a compile-time error"], "answer": 1, "explanation": "When an array is created with new, every element is automatically initialized to its type's default value, and the default value for int is 0 (4.3.A.3). Java never leaves elements undefined, -1 is not a default value for any type, and this is valid, compilable code."},
  {"id": "4.3-basic-03", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.3", "prompt": "boolean[] flags = new boolean[4];\nWhat is the value of flags[0] immediately after this statement executes?", "choices": ["true", "1", "false", "null"], "answer": 2, "explanation": "The default value for a boolean element created with new is false (4.3.A.3). It is not true, since Java does not assume a positive default, boolean values are never represented as 1, and null only applies to reference types."},
  {"id": "4.3-basic-04", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.3", "prompt": "String[] labels = new String[5];\nWhat is the value of labels[2] immediately after this statement executes?", "choices": ["An empty string \"\"", "0", "\"null\"", "null"], "answer": 3, "explanation": "String is a reference type, so an unset element created with new defaults to the value null, not an empty string (4.3.A.3). It is not the numeric default 0, and it is not the text \"null\", which would be a String containing four characters rather than the actual null reference."},
  {"id": "4.3-basic-05", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.2", "prompt": "An array named playerIds has 8 elements. What index refers to the last element in the array?", "choices": ["7", "8", "playerIds.length", "9"], "answer": 0, "explanation": "Valid indices run from 0 through one less than the array's length, so the last element of an 8-element array is at index 7 (4.3.A.2). The value 8 is the array's length, not a valid index, playerIds.length also evaluates to 8, and 9 is even further outside the valid range."},
  {"id": "4.3-basic-06", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.6", "prompt": "An array named quizScores is declared with 10 elements. Which of the following is a valid index that can be used to access an element of quizScores?", "choices": ["10", "9", "-1", "quizScores.length"], "answer": 1, "explanation": "Valid index values run from 0 through one less than the array's length, so 9 is a valid index for a 10-element array (4.3.A.6). The value 10 and the expression quizScores.length both equal the array's length, which is one past the last valid index, and negative index values are never valid."},
  {"id": "4.3-basic-07", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.5", "prompt": "int[] levels = {3, 7, 11, 15};\nWhat value does levels[2] refer to?", "choices": ["3", "7", "11", "15"], "answer": 2, "explanation": "Array indices start at 0, so levels[2] refers to the third value in the initializer list, which is 11 (4.3.A.5). The value 3 is at index 0, 7 is at index 1, and 15 is at index 3."},
  {"id": "4.3-basic-08", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.5", "prompt": "int[] points = new int[4];\npoints[1] = 25;\nWhat is the value of points[1] after this code executes?", "choices": ["0", "1", "4", "25"], "answer": 3, "explanation": "Square brackets are used to directly assign a new value to an array element, so points[1] becomes 25 (4.3.A.5). The value 0 was only the default before the assignment, and 1 and 4 are unrelated numbers that do not appear in the assignment."},
  {"id": "4.3-basic-09", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.6", "prompt": "int[] codes = new int[5];\nWhich statement will cause an ArrayIndexOutOfBoundsException when executed?", "choices": ["codes[5] = 10;", "codes[0] = 10;", "codes[4] = 10;", "codes[1] = 10;"], "answer": 0, "explanation": "An array of length 5 has valid indices 0 through 4, so codes[5] is one past the last valid index and throws an ArrayIndexOutOfBoundsException (4.3.A.6). Indices 0, 4, and 1 are all within the valid range and execute without error."},
  {"id": "4.3-basic-10", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.1", "prompt": "Which of the following best describes what an array can store?", "choices": ["Values of any combination of different data types in the same array", "Multiple values that are all the same declared type", "Exactly one value at a time", "Only object references, never primitive values"], "answer": 1, "explanation": "An array stores multiple values that are all the same declared type, whether primitive or object references (4.3.A.1). Arrays cannot mix different data types together, they hold more than a single value, and they may store either primitives or references, not references exclusively."},
  {"id": "4.3-basic-11", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.1", "prompt": "A student has a class named Book from a class project. Which declaration correctly creates an array capable of holding 10 Book objects?", "choices": ["int[] books = new int[10];", "Book books = new Book[10];", "Book[] books = new Book[10];", "Book[10] books = new Book();"], "answer": 2, "explanation": "An array of a class type is declared with the class name followed by square brackets, so Book[] books = new Book[10]; correctly creates an array of 10 Book references (4.3.A.1). The first choice uses the wrong element type entirely, and the second and fourth choices use invalid array declaration syntax."},
  {"id": "4.3-basic-12", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.2", "prompt": "Which statement correctly creates an array named ratings capable of holding 12 double values, with all elements set to their default value?", "choices": ["double ratings = new double[12];", "double[] ratings = new double(12);", "double[] ratings[12];", "double[] ratings = new double[12];"], "answer": 3, "explanation": "The correct syntax for creating an array with new is type[] name = new type[size];, so double[] ratings = new double[12]; is correct (4.3.A.2). The first choice omits the brackets on the declared type, the second uses parentheses instead of brackets after new, and the third places brackets incorrectly after the variable name with no new keyword."},
  {"id": "4.3-basic-13", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.5", "prompt": "int[] inventory = {12, 8, 20};\ninventory[1] += 5;\nWhat is the value of inventory[1] after this code executes?", "choices": ["13", "8", "5", "17"], "answer": 0, "explanation": "The compound assignment operator += adds the right-hand value to the element's current value, so inventory[1] becomes 8 + 5 = 13 (4.3.A.5). The value 8 was only the value before the update, 5 is only the amount added, and 17 does not match the correct calculation."},
  {"id": "4.3-basic-14", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.4", "prompt": "double[] prices = {4.5, 9.0, 12.75, 6.25, 3.0};\nWhat is the value of prices.length after this statement executes?", "choices": ["4", "5", "6", "0"], "answer": 1, "explanation": "An initializer list establishes the array's length based on the number of values listed, and this list contains 5 values, so prices.length is 5 (4.3.A.4, 4.3.A.2). The length is not 4 or 6, and it is not 0, since the array was created with values already in it."},
  {"id": "4.3-basic-15", "course": "csa", "topic": "4.3", "tier": "basic", "lo": "4.3.A.6", "prompt": "int[] ids = new int[3];\nWhich of the following statements will cause an ArrayIndexOutOfBoundsException?", "choices": ["ids[0] = 100;", "ids[2] = 100;", "ids[-1] = 100;", "ids[1] = 100;"], "answer": 2, "explanation": "A negative index is never a valid index for any array, regardless of the array's length, so ids[-1] causes an ArrayIndexOutOfBoundsException (4.3.A.6). Indices 0, 2, and 1 are all within the valid range of 0 through 2 for a 3-element array."},
  {"id": "4.3-intermediate-01", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.3", "prompt": "A student writes the following code.\nint[] tallies = new int[5];\ntallies[0] = 3;\ntallies[3] = 7;\nWhat are the contents of tallies after this code executes?", "choices": ["{3, 0, 0, 7, 0}", "{3, 7, 0, 0, 0}", "{0, 3, 0, 7, 0}", "{3, 0, 7, 0, 0}"], "answer": 0, "explanation": "tallies is created with new, so every element defaults to 0 except the two that are explicitly assigned; index 0 becomes 3 and index 3 becomes 7, giving {3, 0, 0, 7, 0} (4.3.A.3, 4.3.A.5). The other options place the assigned values at the wrong indices."},
  {"id": "4.3-intermediate-02", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.6", "prompt": "A student intends to store 5 exam scores using the following code.\nint[] examScores = new int[4];\nexamScores[0] = 88;\nexamScores[1] = 91;\nexamScores[2] = 79;\nexamScores[3] = 95;\nexamScores[4] = 84;\nWhen this code runs, an ArrayIndexOutOfBoundsException occurs. Which change would fix the problem so all five scores are stored as intended?", "choices": ["Change examScores[4] = 84; to examScores[3] = 84;", "Remove the line examScores[4] = 84;", "Change examScores[0] = 88; to examScores[1] = 88;", "Change int[] examScores = new int[4]; to int[] examScores = new int[5];"], "answer": 3, "explanation": "The array was declared one element too short for five scores, so index 4 is invalid; increasing the declared size to 5 makes index 4 valid while preserving all five intended scores (4.3.A.2, 4.3.A.6). Overwriting index 3, removing the fifth score, or renumbering the first score would each lose data rather than fix the underlying size problem."},
  {"id": "4.3-intermediate-03", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.4", "prompt": "A student wants to create and initialize an array named weights containing the values 12.5, 9.0, and 15.25 in a single statement. Which of the following statements is valid Java code that accomplishes this?", "choices": ["double weights = {12.5, 9.0, 15.25};", "double[] weights = new double{12.5, 9.0, 15.25};", "double[] weights = {12.5, 9.0, 15.25};", "double[] weights = new double[]{12.5; 9.0; 15.25};"], "answer": 2, "explanation": "An initializer list is written as type[] name = {values, separated, by, commas};, so double[] weights = {12.5, 9.0, 15.25}; is valid (4.3.A.4). The first choice omits the array brackets on the declared type, the second is missing brackets after new, and the fourth incorrectly separates the values with semicolons instead of commas."},
  {"id": "4.3-intermediate-04", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.5", "prompt": "int[] balances = {100, 250, 60};\nbalances[2] *= 3;\nbalances[0] += 20;\nWhat are the contents of balances after this code executes?", "choices": ["{100, 250, 180}", "{120, 250, 60}", "{100, 250, 63}", "{120, 250, 180}"], "answer": 3, "explanation": "The statement balances[2] *= 3 changes index 2 from 60 to 180, and balances[0] += 20 changes index 0 from 100 to 120, giving {120, 250, 180} (4.3.A.5). The other options apply only one of the two updates or miscompute one of the operations."},
  {"id": "4.3-intermediate-05", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.1", "prompt": "A student has a Player class with instance variables for name and score. The student writes the following declaration.\nPlayer[] roster = new Player[4];\nWhat is true about roster immediately after this statement executes?", "choices": ["roster has 4 elements, and each element currently holds the value null since no Player objects have been created yet", "roster has 4 elements, and each element already refers to a distinct Player object with default field values", "roster is not an array, since Player is not a primitive type", "roster has 0 elements until Player objects are explicitly added"], "answer": 0, "explanation": "Arrays can store object references as well as primitive values, and an array of a reference type created with new has each element default to null until a real object is assigned (4.3.A.1, 4.3.A.3). No Player objects are automatically constructed, arrays of class types are entirely legal, and the array already has 4 elements as soon as it is created."},
  {"id": "4.3-intermediate-06", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.6", "prompt": "An array named ticketCounts is created with the statement int[] ticketCounts = new int[6];. A student proposes three statements to access an element.\nI. ticketCounts[6] = 10;\nII. ticketCounts[5] = 10;\nIII. ticketCounts[0] = 10;\nWhich of these statements will cause an ArrayIndexOutOfBoundsException?", "choices": ["II only", "I only", "I and II only", "III only"], "answer": 1, "explanation": "ticketCounts has 6 elements, so valid indices run from 0 through 5; statement I uses index 6, which is one past the last valid index and causes the exception (4.3.A.6). Statements II and III use indices 5 and 0, both of which are within the valid range."},
  {"id": "4.3-intermediate-07", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.2", "prompt": "A student writes the following code.\nint[] roomNumbers = new int[10];\nroomNumbers.length = 15;\nWhat is the result of this code?", "choices": ["roomNumbers now has 15 elements", "roomNumbers now has 10 elements and one of them is 15", "This code produces a compile-time error, because length cannot be reassigned once an array is created", "roomNumbers is unaffected because Java silently ignores the second statement"], "answer": 2, "explanation": "An array's length is fixed at the time of creation and cannot be changed afterward, and attempting to assign a new value to it produces a compile-time error rather than being silently skipped (4.3.A.2). The array does not grow to 15 elements, and no element is set to the value 15 either."},
  {"id": "4.3-intermediate-08", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.3", "prompt": "A student creates an array as follows.\ndouble[] distances = new double[4];\ndistances[1] = 12.5;\ndistances[3] = 8.0;\nWhat are the contents of distances after this code executes?", "choices": ["{12.5, 0.0, 8.0, 0.0}", "{0.0, 12.5, 8.0, 0.0}", "{0.0, 0.0, 12.5, 8.0}", "{0.0, 12.5, 0.0, 8.0}"], "answer": 3, "explanation": "distances is created with new, so unset elements default to 0.0; index 1 becomes 12.5 and index 3 becomes 8.0, giving {0.0, 12.5, 0.0, 8.0} (4.3.A.3, 4.3.A.5). The other options place the assigned values at incorrect indices."},
  {"id": "4.3-intermediate-09", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.1", "prompt": "A method is defined as follows.\npublic static void bumpValue(int[] data, int index, int amount)\n{\n    data[index] += amount;\n}\nA separate method contains the following code.\nint[] readings = new int[4];\nbumpValue(readings, 2, 9);\nWhat are the contents of readings immediately after bumpValue(readings, 2, 9); executes?", "choices": ["{0, 0, 9, 0}", "{9, 0, 0, 0}", "readings is unaffected, because bumpValue only modifies its own local copy of the array", "{0, 0, 0, 9}"], "answer": 0, "explanation": "Since readings is an array, it is a reference type, so passing it to bumpValue lets the method modify the same array object the caller holds; index 2 changes from its default 0 to 0 + 9 = 9 (4.3.A.1). The array is not unaffected, and the other options place the change at the wrong index."},
  {"id": "4.3-intermediate-10", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.4", "prompt": "String[] cities = {\"Reno\", \"Boise\", \"Tulsa\", \"Akron\"};\nWhat is the value of cities[cities.length - 2]?", "choices": ["\"Akron\"", "\"Tulsa\"", "\"Boise\"", "\"Reno\""], "answer": 1, "explanation": "The initializer list gives cities a length of 4, so cities.length - 2 evaluates to 2, and cities[2] is \"Tulsa\" (4.3.A.4, 4.3.A.5). The other choices correspond to different indices in the list."},
  {"id": "4.3-intermediate-11", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.6", "prompt": "An array named codes has 7 elements. A student wants to access the very last element using a variable rather than a literal number. Which expression correctly accesses the last element?", "choices": ["codes[7]", "codes[codes.length]", "codes[codes.length - 1]", "codes[-1]"], "answer": 2, "explanation": "The last valid index of an array is always one less than its length, so codes[codes.length - 1] correctly accesses the last element (4.3.A.2, 4.3.A.6). The first two expressions both evaluate to index 7, which is out of range, and a negative index is never valid."},
  {"id": "4.3-intermediate-12", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.5", "prompt": "int[] votes = {5, 12, 3, 9};\nvotes[1] = 20;\nvotes[3] = 1;\nWhat are the contents of votes after this code executes?", "choices": ["{5, 20, 3, 9}", "{20, 12, 3, 1}", "{5, 12, 20, 1}", "{5, 20, 3, 1}"], "answer": 3, "explanation": "The statement votes[1] = 20; sets index 1 to 20, and votes[3] = 1; sets index 3 to 1, while the other elements remain unchanged, giving {5, 20, 3, 1} (4.3.A.5). The other options either apply only one of the changes or place a change at the wrong index."},
  {"id": "4.3-intermediate-13", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.4", "prompt": "A student proposes two ways to declare and initialize an array of 3 boolean values.\nI. boolean[] flags = {true, false, true};\nII. boolean[] flags = new boolean[]{true, false, 1};\nWhich of these statements will compile successfully?", "choices": ["I only", "II only", "Both I and II", "Neither I nor II"], "answer": 0, "explanation": "Statement I lists three valid boolean literals inside the initializer list and compiles correctly (4.3.A.4). Statement II includes the int literal 1 where a boolean value is required, which is a type mismatch and causes a compile-time error."},
  {"id": "4.3-intermediate-14", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.2", "prompt": "A student writes the following code.\nint[] counters = new int[6];\nint total = counters.length + counters[0];\nWhat is the value of total after this code executes?", "choices": ["0", "6", "36", "12"], "answer": 1, "explanation": "counters.length evaluates to 6, and counters[0] defaults to 0 since the array was just created with new, so total is 6 + 0 = 6 (4.3.A.2, 4.3.A.3). The other values do not correctly combine the array's length with its default element value."},
  {"id": "4.3-intermediate-15", "course": "csa", "topic": "4.3", "tier": "intermediate", "lo": "4.3.A.6", "prompt": "int[] stockLevels = new int[5];\nA student writes three statements intended to update stockLevels.\nI. stockLevels[4] += 3;\nII. stockLevels[5] -= 2;\nIII. stockLevels[0] *= 4;\nWhich statement(s), if executed, will cause an ArrayIndexOutOfBoundsException?", "choices": ["I only", "III only", "II only", "I and III only"], "answer": 2, "explanation": "stockLevels has 5 elements, so valid indices run from 0 through 4; statement II uses index 5, which is one past the last valid index and causes the exception (4.3.A.6). Statements I and III use indices 4 and 0, both of which are valid."},
  {"id": "4.3-complex-01", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.6", "prompt": "A student writes the following code to track the temperature recorded at the start and end of 5 class periods.\nint[] periodTemps = new int[5];\nperiodTemps[0] = 68;\nperiodTemps[4] = 74;\nint lastValid = periodTemps.length - 1;\nperiodTemps[lastValid + 1] = 80;\nWhat is the result of executing the last line, periodTemps[lastValid + 1] = 80;?", "choices": ["An ArrayIndexOutOfBoundsException occurs, because lastValid + 1 evaluates to 5, which is outside the valid index range of 0 through 4", "periodTemps[5] is created automatically to hold the value 80, extending the array to length 6", "The statement is ignored, and periodTemps is unaffected", "A compile-time error occurs because lastValid is not a valid index type"], "answer": 0, "explanation": "lastValid equals periodTemps.length - 1, which is 4, so lastValid + 1 evaluates to 5, an index outside the valid range of 0 through 4, producing an ArrayIndexOutOfBoundsException at runtime (4.3.A.6). Arrays never grow automatically to accommodate an out-of-range index, the statement is a runtime error rather than being silently ignored, and an int expression is a perfectly valid index type."},
  {"id": "4.3-complex-02", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.4", "prompt": "A student proposes four ways to declare and initialize an array meant to hold exactly 4 whole-number quiz grades.\nI. int[] grades = {88, 91, 76, 95};\nII. int grades[] = {88, 91, 76, 95};\nIII. int[] grades = new int[4]{88, 91, 76, 95};\nIV. int[] grades = new int[]{88, 91, 76, 95};\nWhich of these declarations will cause a compile-time error?", "choices": ["I only", "III only", "II only", "IV only"], "answer": 1, "explanation": "Statement III illegally specifies an explicit size, new int[4], together with an initializer list, which Java does not permit; the size must be implied by the number of values in the list rather than stated explicitly when new is combined with braces (4.3.A.4). Statement I uses the standard initializer-list form, statement II legally places the brackets after the identifier, and statement IV correctly omits the size when combining new with an initializer list, so none of those three produce an error."},
  {"id": "4.3-complex-03", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.3", "prompt": "A student has a Coupon class with a constructor Coupon(double amount) that sets an instance variable. The student writes the following code.\nCoupon[] coupons = new Coupon[3];\ncoupons[1] = new Coupon(5.00);\nSystem.out.println(coupons[0]);\nSystem.out.println(coupons[2]);\nWhat happens when the two println statements execute?", "choices": ["Both statements print a Coupon object with amount 0.00, since Coupon has a default constructor", "Both statements throw an ArrayIndexOutOfBoundsException, since only index 1 was ever assigned", "The code fails to compile, because not every element of coupons was explicitly assigned a Coupon object", "Both statements print null, since coupons[0] and coupons[2] were never assigned a Coupon object and default to null for a reference type"], "answer": 3, "explanation": "coupons is an array of a reference type, so any element that is never explicitly assigned defaults to null rather than to some automatically constructed object (4.3.A.3, 4.3.A.1). Indices 0 and 2 are still valid indices within the array, so no exception occurs, and the code compiles and runs fine, simply printing null for the untouched elements."},
  {"id": "4.3-complex-04", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.6", "prompt": "A student's code is intended to store the attendance count for each of 6 class periods, using periods 1 through 6 as natural labels.\nint[] attendance = new int[6];\nattendance[1] = 24;\nattendance[6] = 22;\nWhen this code runs, an ArrayIndexOutOfBoundsException occurs on the last line. The student wants period 6's attendance to be stored at index 5, matching how the rest of the array is indexed starting at index 0 for period 1. Which change correctly fixes the bug while preserving this 0-indexed scheme?", "choices": ["Change int[] attendance = new int[6]; to int[] attendance = new int[7];", "Change attendance[1] = 24; to attendance[0] = 24;, and leave attendance[6] = 22; unchanged", "Remove the line attendance[6] = 22; entirely", "Change attendance[6] = 22; to attendance[5] = 22;, and change attendance[1] = 24; to attendance[0] = 24; to correctly reflect the 0-indexed scheme for period 1"], "answer": 3, "explanation": "To store 6 periods using a 0-indexed scheme where index 0 represents period 1, every period's data must be shifted down by one index, so period 6 belongs at index 5 and period 1 belongs at index 0 (4.3.A.5, 4.3.A.6). Growing the array to length 7 fixes the exception but abandons the intended 0-indexed scheme by leaving index 0 unused, since period 1's value would still be stored at index 1 instead of index 0; changing only one of the two lines leaves the indexing scheme inconsistent, and deleting the line loses period 6's data entirely."},
  {"id": "4.3-complex-05", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.5", "prompt": "int[] tally = {10, 4, 7, 2, 9};\ntally[2] *= 2;\ntally[4] -= 3;\ntally[0] += tally[2];\nWhat are the contents of tally after all three statements execute, in order?", "choices": ["{24, 4, 14, 2, 6}", "{10, 4, 14, 2, 6}", "{24, 4, 7, 2, 6}", "{14, 4, 14, 2, 6}"], "answer": 0, "explanation": "The statement tally[2] *= 2 makes tally[2] equal 7 * 2 = 14, and tally[4] -= 3 makes tally[4] equal 9 - 3 = 6; then tally[0] += tally[2] uses the already-updated value of tally[2], which is 14, so tally[0] becomes 10 + 14 = 24, giving {24, 4, 14, 2, 6} (4.3.A.5). The other options either fail to use the updated value of tally[2] in the third statement or forget to apply one of the earlier operations."},
  {"id": "4.3-complex-06", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.4", "prompt": "A student considers five candidate declarations, each intended to create an array of 4 double values representing lap times.\nI. double[] lapTimes = {12.4, 11.9, 13.0, 12.7};\nII. double[] lapTimes = new double[4];\nIII. double lapTimes[] = new double[4];\nIV. double[] lapTimes = new double[4.0];\nV. double[] lapTimes = {12.4, 11.9, 13.0, 12};\nWhich of these declarations will cause a compile-time error?", "choices": ["III and V only", "IV only", "I and II only", "II, III, and IV only"], "answer": 1, "explanation": "Declaration IV attempts to specify an array's size using 4.0, a double literal, but an array's size must be a non-negative int expression, so it fails to compile (4.3.A.2, 4.3.A.4). Declarations I and II use standard, correct syntax, III is a legal alternate placement of the brackets, and V is legal because the int literal 12 widens automatically to a double within a double array's initializer list, so only IV causes an error."},
  {"id": "4.3-complex-07", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.6", "prompt": "A method is defined as follows.\npublic static void applyBonus(int[] scores, int index)\n{\n    scores[index] += 10;\n}\nA separate method contains the following code.\nint[] finalScores = {70, 82, 95};\napplyBonus(finalScores, 1);\napplyBonus(finalScores, 3);\nWhat happens when this code executes?", "choices": ["Both calls succeed, and finalScores becomes {70, 92, 95, 10}", "Both calls succeed, and finalScores becomes {70, 92, 105}", "The first call succeeds and updates finalScores to {70, 92, 95}, but the second call causes an ArrayIndexOutOfBoundsException, because index 3 is outside the valid range of 0 through 2", "Neither call has any effect on finalScores, because arrays passed to methods are always copied"], "answer": 2, "explanation": "finalScores has length 3, so valid indices run from 0 through 2 (4.3.A.6); the first call correctly updates index 1 to 92, but the second call attempts index 3, which is out of range and throws an exception at runtime. Since arrays are reference types, applyBonus does modify the caller's actual array (4.3.A.1) rather than a copy, and no new element at index 3 gets created just because it was referenced."},
  {"id": "4.3-complex-08", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.3", "prompt": "A student writes the following code.\nboolean[] eligible = new boolean[5];\neligible[0] = true;\neligible[3] = true;\nA classmate proposes four descriptions of the array's contents immediately after this code executes.\nI. {true, true, true, true, true}\nII. {true, false, false, false, false}\nIII. {false, false, false, true, false}\nIV. {true, false, false, true, false}\nWhich description correctly matches the contents of eligible?", "choices": ["I", "II", "III", "IV"], "answer": 3, "explanation": "eligible is created with new, so every element defaults to false (4.3.A.3), except index 0 and index 3, which are explicitly set to true, giving {true, false, false, true, false}, matching IV. Description I incorrectly assumes every element became true, II forgets to set index 3, and III forgets to set index 0."},
  {"id": "4.3-complex-09", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.6", "prompt": "int[] rankings = {50, 40, 30, 20, 10};\nint i = 2;\nA student writes four expressions intended to access valid elements of rankings.\nI. rankings[i + 2]\nII. rankings[i - 3]\nIII. rankings[rankings.length - 1]\nIV. rankings[rankings.length]\nWhich of these expressions, if evaluated, would cause an ArrayIndexOutOfBoundsException?", "choices": ["II and IV only", "I and III only", "I only", "II only"], "answer": 0, "explanation": "With i equal to 2, expression II evaluates to rankings[-1], a negative index, and expression IV evaluates to rankings[5], which equals rankings.length and is one past the last valid index; both fall outside the valid range of 0 through 4 (4.3.A.6). Expression I evaluates to rankings[4], the last valid index, and expression III, rankings.length - 1, is exactly the correct way to reference the last valid element, so neither I nor III causes an exception."},
  {"id": "4.3-complex-10", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.4", "prompt": "A student attempts to create and populate an array of 4 String values representing team names using the following code.\nString[] teams;\nteams = {\"Hawks\", \"Wolves\", \"Bears\", \"Foxes\"};\nWhen the student tries to compile this code, it fails. What is the most likely reason?", "choices": ["String arrays cannot use initializer lists, only int and double arrays can", "An initializer list using only curly braces can be used to initialize an array in the same statement it is declared, but not in a separate assignment statement after the array has already been declared", "The team names contain more than 3 characters, which is not allowed in an array initializer list", "Arrays of String cannot exceed 3 elements in Java"], "answer": 1, "explanation": "A bare initializer list, one written with only curly braces and no new keyword, is legal only as part of the declaration statement, such as String[] teams = {...};; once teams has already been declared on its own line, a later assignment must use new String[]{...} instead (4.3.A.4). Initializer lists work for any array type, including String, there is no character-length restriction on element values, and there is no size cap of 3 on String arrays."},
  {"id": "4.3-complex-11", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.1", "prompt": "A student has a class named Account with a method deposit(double amount) that increases the account's balance. The student writes the following code.\nAccount[] accounts = new Account[3];\naccounts[0] = new Account(100.00);\naccounts[1] = new Account(250.00);\naccounts[0].deposit(50.00);\naccounts[2] = accounts[0];\naccounts[2].deposit(25.00);\nWhat is the balance of the Account object referenced by accounts[0] after this code executes?", "choices": ["100.00", "150.00", "175.00", "225.00"], "answer": 2, "explanation": "accounts[0] starts at 100.00, and deposit(50.00) raises it to 150.00; the statement accounts[2] = accounts[0]; copies the reference, not a new object, so accounts[2] refers to the very same Account object as accounts[0] (4.3.A.1). When deposit(25.00) is called through accounts[2], it modifies that shared object, so accounts[0]'s balance also becomes 175.00, rather than staying at 100.00 or 150.00 or reaching 225.00."},
  {"id": "4.3-complex-12", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.6", "prompt": "int[] pinCodes = {4, 8, 15, 16, 23, 42};\nA student writes five statements intended to modify elements of pinCodes.\nI. pinCodes[0] = 1;\nII. pinCodes[5] = 1;\nIII. pinCodes[6] = 1;\nIV. pinCodes[pinCodes.length - 1] = 1;\nV. pinCodes[pinCodes.length] = 1;\nWhich statements, if executed, would cause an ArrayIndexOutOfBoundsException?", "choices": ["I and III only", "II and V only", "III and IV only", "III and V only"], "answer": 3, "explanation": "pinCodes has 6 elements from its initializer list, so valid indices run from 0 through 5 (4.3.A.2, 4.3.A.6). Statement III uses index 6 directly, and statement V uses pinCodes.length, which also evaluates to 6, both one past the last valid index. Statements I, II, and IV all use valid indices, 0, 5, and 5 respectively, so they execute without error."},
  {"id": "4.3-complex-13", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.3", "prompt": "double[] measurements = new double[4];\nmeasurements[2] = 7.5;\ndouble result = measurements[0] + measurements[1] + measurements[2] + measurements[3];\nWhat is the value of result after this code executes?", "choices": ["7.5", "0.0", "30.0", "The code fails to compile because measurements[0], measurements[1], and measurements[3] were never assigned a value"], "answer": 0, "explanation": "measurements is created with new, so every element defaults to 0.0 except index 2, which is explicitly set to 7.5 (4.3.A.3), making the sum 0.0 + 0.0 + 7.5 + 0.0 = 7.5. The result is not 0.0, since index 2 does hold a nonzero value, and it does not fail to compile, since array elements created with new are always automatically initialized rather than left unassigned."},
  {"id": "4.3-complex-14", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.5", "prompt": "int[] inventory = {50, 30, 20};\ninventory[1] = inventory[0] + inventory[2];\ninventory[0] = inventory[1] - inventory[2];\nWhat are the contents of inventory after both assignment statements execute, in order?", "choices": ["{70, 70, 20}", "{50, 70, 20}", "{30, 70, 20}", "{70, 50, 20}"], "answer": 1, "explanation": "The first statement computes inventory[1] = inventory[0] + inventory[2] = 50 + 20 = 70, so inventory becomes {50, 70, 20}; the second statement then computes inventory[0] = inventory[1] - inventory[2] using the already-updated inventory[1], giving 70 - 20 = 50, which leaves inventory[0] unchanged at 50, so the final contents are {50, 70, 20} (4.3.A.5). The other options either use the original, pre-update value of inventory[0] when computing the second statement or apply the arithmetic to the wrong elements."},
  {"id": "4.3-complex-15", "course": "csa", "topic": "4.3", "tier": "complex", "lo": "4.3.A.2", "prompt": "A student is filling an array with the squares of the first several positive integers, one index-based assignment at a time.\nint[] squares = new int[4];\nsquares[0] = 1;\nsquares[1] = 4;\nsquares[2] = 9;\nsquares[3] = 16;\nsquares[4] = squares[3] + 9;\nThe student wants squares to end up holding five perfect squares: 1, 4, 9, 16, and 25. Which change to the code above correctly achieves this goal without causing a runtime error?", "choices": ["Change squares[4] = squares[3] + 9; to squares[3] = squares[3] + 9;", "Remove the line squares[4] = squares[3] + 9; entirely, leaving only four elements", "Change int[] squares = new int[4]; to int[] squares = new int[5]; so that index 4 becomes a valid index for the fifth value", "Change squares[4] = squares[3] + 9; to squares[5] = squares[3] + 9;"], "answer": 2, "explanation": "To store a fifth value at index 4, the array's length must be increased to 5 when it is created, since length is fixed at creation and index 4 is only valid in an array of length 5 or more (4.3.A.2, 4.3.A.6). Reassigning to squares[3] would overwrite the fourth square instead of adding a fifth, removing the line abandons the goal of five squares entirely, and changing the index to 5 would still be out of bounds for an array that remains at length 4."},
  {"id": "4.4-basic-01", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] ticketPrices = {5, 10, 15, 20};\nfor (int i = 0; i < ticketPrices.length; i++)\n{\n    ticketPrices[i] = ticketPrices[i] + 1;\n}\nWhat are the contents of ticketPrices after the code segment executes?", "choices": ["{6, 11, 16, 21}", "{5, 10, 15, 20}", "{6, 10, 15, 20}", "The code throws an ArrayIndexOutOfBoundsException"], "answer": 0, "explanation": "The loop uses the index i to access every element from index 0 through ticketPrices.length - 1, adding 1 to each one, so every element increases by 1 (4.4.A.2). The array is not left unchanged, since the loop body does execute; only the first element changing reflects a mistaken belief that the loop runs once instead of ticketPrices.length times; and no exception occurs because i never reaches an invalid index."},
  {"id": "4.4-basic-02", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.3", "prompt": "Consider the following code segment.\nint[] fuelLevels = {40, 65, 22, 90};\nfor (int level : fuelLevels)\n{\n    System.out.println(level);\n}\nWhat is printed as a result of executing this code segment?", "choices": ["90, then 22, then 65, then 40, each on its own line", "40, then 65, then 22, then 90, each on its own line", "Only 40 and 22, each on its own line, since level only holds even-indexed elements", "The code does not compile because level is never declared with an int index"], "answer": 1, "explanation": "An enhanced for loop assigns the loop variable level a copy of each element in order, starting from index 0 and ending with the last element, so the values print in their original array order (4.4.A.3). Printing them in reverse order describes a different kind of traversal, printing only two values reflects a misunderstanding that the enhanced for loop skips elements, and the code compiles correctly since the enhanced for loop variable does not require an explicit index."},
  {"id": "4.4-basic-03", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] boxWeights = {3, 6, 9, 12};\nint i = 0;\nwhile (i < boxWeights.length)\n{\n    boxWeights[i] = boxWeights[i] * 2;\n    i++;\n}\nWhat are the contents of boxWeights after the code segment executes?", "choices": ["{3, 6, 9, 12}", "The code never terminates because i is never updated", "{6, 12, 18, 24}", "{6, 6, 6, 6}"], "answer": 2, "explanation": "The while loop accesses each index from 0 through boxWeights.length - 1 using i, doubling each element, and i is incremented every iteration so the loop terminates normally (4.4.A.2). The array is not left unchanged, since the loop body executes for every index; the loop does terminate because i++ runs each iteration; and every element is doubled by its own original value, not all set to the same result."},
  {"id": "4.4-basic-04", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.6", "prompt": "A programmer writes the following enhanced for loop.\nint[] rainTotals = {2, 4, 6, 8};\nfor (int total : rainTotals)\n{\n    System.out.println(total);\n}\nWhich indexed for loop produces the exact same output?", "choices": ["for (int i = 1; i <= rainTotals.length; i++)\n{\n    System.out.println(rainTotals[i]);\n}", "for (int i = rainTotals.length - 1; i >= 0; i--)\n{\n    System.out.println(rainTotals[i]);\n}", "for (int i = 0; i < rainTotals.length; i++)\n{\n    System.out.println(i);\n}", "for (int i = 0; i < rainTotals.length; i++)\n{\n    System.out.println(rainTotals[i]);\n}"], "answer": 3, "explanation": "Starting i at 0, stopping before rainTotals.length, and printing rainTotals[i] visits every element in the same order as the enhanced for loop (4.4.A.6). Starting at 1 with <= skips index 0 and throws an exception at the last iteration, counting downward reverses the order, and printing i instead of rainTotals[i] prints the indices rather than the element values."},
  {"id": "4.4-basic-05", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.4", "prompt": "Consider the following code segment.\nint[] stepCounts = {1000, 2000, 3000};\nfor (int steps : stepCounts)\n{\n    steps = steps + 500;\n}\nWhat are the contents of stepCounts after the code segment executes?", "choices": ["{1000, 2000, 3000}", "{1500, 2500, 3500}", "{1500, 2000, 3000}", "The code throws a compile-time error because steps cannot be reassigned"], "answer": 0, "explanation": "The enhanced for loop variable steps holds a copy of each element, so assigning a new value to steps only changes that temporary copy and never changes the original array (4.4.A.4). The array is not increased by 500 in any position, and reassigning the enhanced for loop variable is legal Java, it simply has no lasting effect."},
  {"id": "4.4-basic-06", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.1", "prompt": "Which of the following best describes what it means to traverse an array?", "choices": ["Declaring an array and assigning it a length using the new keyword", "Using a repetition statement to access all or an ordered sequence of the array's elements", "Sorting the elements of the array from smallest to largest", "Copying the entire array into a second array using an assignment statement"], "answer": 1, "explanation": "Traversing an array means using a loop to access all, or an ordered sequence of, its elements (4.4.A.1). Declaring an array only creates it without accessing any elements, sorting is one possible thing a traversal might help accomplish but is not the definition of traversal itself, and copying an array cannot be done with a single assignment statement in Java."},
  {"id": "4.4-basic-07", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] labelIds = new int[5];\nfor (int i = 0; i < labelIds.length; i++)\n{\n    labelIds[i] = i;\n}\nWhat are the contents of labelIds after the code segment executes?", "choices": ["{1, 2, 3, 4, 5}", "{0, 0, 0, 0, 0}", "{0, 1, 2, 3, 4}", "The code throws an ArrayIndexOutOfBoundsException"], "answer": 2, "explanation": "The loop assigns each element labelIds[i] the current value of the index i, and i ranges from 0 through 4, producing {0, 1, 2, 3, 4} (4.4.A.2). The array is not left at its default values, since every element is assigned; the values do not start at 1, since the first index used is 0; and no exception occurs because i never exceeds labelIds.length - 1."},
  {"id": "4.4-basic-08", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.3", "prompt": "A student wants to print the index of an array element alongside its value while traversing an array named voteTallies. Which type of loop must be used to access the index directly?", "choices": ["An enhanced for loop, because the loop variable automatically stores the index", "Either an enhanced for loop or an indexed for loop, since both provide direct access to the index", "A while loop only, since a while loop is the only repetition statement in Java", "An indexed for loop or a while loop, since the enhanced for loop variable never gives direct access to the index"], "answer": 3, "explanation": "An indexed for loop or a while loop tracks an explicit index variable that can be printed directly, while the enhanced for loop variable holds only a copy of each element's value and never gives direct access to its index (4.4.A.3, 4.4.A.2). The enhanced for loop cannot provide the index on its own, and a while loop is not the only repetition statement available in Java."},
  {"id": "4.4-basic-09", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] pageViews = {12, 24, 36, 48};\nint i = 0;\nwhile (i < pageViews.length)\n{\n    pageViews[i] = pageViews[i] - 2;\n    i++;\n}\nWhat are the contents of pageViews after the code segment executes?", "choices": ["{10, 22, 34, 46}", "{12, 24, 36, 48}", "{10, 22, 34, 46, 44}", "The code throws an ArrayIndexOutOfBoundsException"], "answer": 0, "explanation": "The while loop's condition i < pageViews.length keeps i within valid bounds while subtracting 2 from every element, producing {10, 22, 34, 46} (4.4.A.2). The array does not stay unchanged, since every element is modified; a fifth value cannot appear, since the array only ever has four elements; and no exception occurs because i stops before reaching an invalid index."},
  {"id": "4.4-basic-10", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.6", "prompt": "A programmer writes the following indexed for loop.\nint[] paintCans = {3, 6, 9};\nfor (int i = 0; i < paintCans.length; i++)\n{\n    System.out.println(paintCans[i]);\n}\nWhich enhanced for loop produces the exact same output?", "choices": ["for (int i : paintCans)\n{\n    System.out.println(i);\n    i++;\n}", "for (int can : paintCans)\n{\n    System.out.println(can);\n}", "for (int can : paintCans)\n{\n    System.out.println(paintCans[can]);\n}", "for (int can = 0; can < paintCans.length; can++)\n{\n    System.out.println(can);\n}"], "answer": 1, "explanation": "An enhanced for loop that prints the loop variable directly visits and prints every element in order, matching the original indexed for loop (4.4.A.6). Incrementing the enhanced for loop variable has no effect on the traversal itself, using the loop variable as an index inside paintCans[can] is invalid since can already holds an element's value rather than an index, and the last option is still an indexed for loop that prints indices, not element values."},
  {"id": "4.4-basic-11", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.4", "prompt": "Consider the following code segment.\nint[] tempsF = {70, 75, 80};\nfor (int t : tempsF)\n{\n    t = 0;\n}\nWhat are the contents of tempsF after the code segment executes?", "choices": ["{0, 0, 0}", "{0, 75, 80}", "{70, 75, 80}", "The code throws a compile-time error"], "answer": 2, "explanation": "Assigning a value to the enhanced for loop variable t only overwrites the local copy for that iteration; it never changes the element actually stored in the array, so tempsF is unaffected (4.4.A.4). The array is not zeroed out in whole or in part, and this code is legal Java that compiles without error."},
  {"id": "4.4-basic-12", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.3", "prompt": "An array named coinValues contains 6 elements. Consider the following code segment.\nint hits = 0;\nfor (int coin : coinValues)\n{\n    hits++;\n}\nHow many times does the loop body execute?", "choices": ["0 times", "5 times", "7 times", "6 times"], "answer": 3, "explanation": "An enhanced for loop executes its body once for each element in the array, and coinValues contains 6 elements, so the body runs exactly 6 times regardless of what coin's value is used for (4.4.A.3). The loop does not skip the first or last element, and it does not run an extra time beyond the number of elements."},
  {"id": "4.4-basic-13", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.1", "prompt": "A student wants to write a loop that visits every element of an array named quizGrades exactly once, in order from the first element to the last. Which loop header correctly accomplishes this traversal?", "choices": ["for (int i = 0; i < quizGrades.length; i++)", "for (int i = 0; i <= quizGrades.length; i++)", "for (int i = 1; i < quizGrades.length; i++)", "for (int i = quizGrades.length; i > 0; i--)"], "answer": 0, "explanation": "Starting i at 0 and stopping the loop before i reaches quizGrades.length visits every valid index exactly once in order, which is a correct traversal (4.4.A.1, 4.4.A.2). Using <= would attempt to access an invalid index one past the end of the array, starting at 1 would skip the first element, and starting at quizGrades.length would immediately reference an invalid index on the first iteration."},
  {"id": "4.4-basic-14", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] raceTimes = {55, 60, 65, 70};\nfor (int i = 1; i < raceTimes.length; i++)\n{\n    raceTimes[i] = raceTimes[i] - 5;\n}\nWhich element of raceTimes is not modified by this loop?", "choices": ["raceTimes[1]", "raceTimes[0]", "raceTimes[2]", "raceTimes[3]"], "answer": 1, "explanation": "Because the loop starts at i = 1 instead of i = 0, the element at index 0 is never accessed or modified, while indices 1 through 3 all have 5 subtracted from them (4.4.A.2). The other three indices are each visited at least once by the loop, so they are not the correct answer."},
  {"id": "4.4-basic-15", "course": "csa", "topic": "4.4", "tier": "basic", "lo": "4.4.A.6", "prompt": "A student needs to write a loop over an array named salaryList that both reads each element's value and modifies the element at the following index, using an expression such as salaryList[i + 1]. Which type of loop is most appropriate for this task?", "choices": ["An enhanced for loop, since it automatically provides access to neighboring elements", "Either loop type works identically, since enhanced for loops can access any index", "An indexed for loop, since it provides direct access to the index needed to reference salaryList[i + 1]", "A do-while loop, since it is the only loop that can access more than one index at a time"], "answer": 2, "explanation": "Because the task requires referencing an index other than the current element's own index, an indexed for loop (or while loop) is needed to compute and use that index directly, such as i + 1 (4.4.A.6, 4.4.A.2). An enhanced for loop's variable does not expose any index at all, so it cannot reference a neighboring element, and Java's do-while loop has no special ability to access multiple indices at once."},
  {"id": "4.4-intermediate-01", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.4", "prompt": "Consider the following code segment.\nint[] inventoryCounts = {12, 18, 24};\nfor (int count : inventoryCounts)\n{\n    count = count + 100;\n    System.out.println(count);\n}\nSystem.out.println(inventoryCounts[0]);\nWhat is printed as a result of executing this code segment?", "choices": ["112\n118\n124\n112", "112, 118, and 124 are each printed on their own line, then 12 is printed", "12, 18, and 24 are each printed on their own line, then 12 is printed", "112, 118, and 124 are each printed on their own line, then 112 is printed"], "answer": 1, "explanation": "Inside the loop, count is a copy of each element plus 100, so 112, 118, and 124 print in turn; but since reassigning count never changes the array itself, inventoryCounts[0] still holds its original value of 12 when printed afterward (4.4.A.4). Printing 12, 18, and 24 unmodified ignores the + 100 done inside the loop, and printing 112 afterward incorrectly assumes the array was permanently changed."},
  {"id": "4.4-intermediate-02", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.5", "prompt": "A Balloon class is defined as follows.\npublic class Balloon\n{\n    private double height;\n    public Balloon(double startHeight)\n    {\n        height = startHeight;\n    }\n    public void inflate(double amount)\n    {\n        height = height + amount;\n    }\n    public double getHeight()\n    {\n        return height;\n    }\n}\nConsider the following code segment.\nBalloon[] balloons = {new Balloon(2.0), new Balloon(5.0)};\nfor (Balloon b : balloons)\n{\n    b.inflate(1.0);\n}\nWhat are the height values of the Balloon objects referenced by balloons after this code executes?", "choices": ["2.0 and 5.0, unchanged, because the array still holds the same object references", "3.0 and 6.0 for the first traversal only, then reset back to 2.0 and 5.0", "3.0 and 6.0, because calling inflate() on b modifies the object that b refers to, which is the same object stored in the array", "The code does not compile because b cannot call a method inside an enhanced for loop"], "answer": 2, "explanation": "Even though b is a copy of the object reference, that copy still refers to the same Balloon object stored in the array, so calling the mutator inflate() on b changes that object's height field, resulting in 3.0 and 6.0 (4.4.A.5). The heights are not left unchanged, since inflate() does execute; there is no reset back to the original values; and calling a method on an enhanced for loop variable is valid, compiling code."},
  {"id": "4.4-intermediate-03", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.5", "prompt": "Using the same Balloon class from the previous problem, consider the following code segment.\nBalloon[] balloons = {new Balloon(2.0), new Balloon(5.0)};\nfor (Balloon b : balloons)\n{\n    b = new Balloon(0.0);\n}\nWhat are the height values of the Balloon objects referenced by balloons after this code executes?", "choices": ["0.0 and 0.0, because b was reassigned to a new Balloon inside the loop", "3.0 and 6.0, because a new Balloon was created and inflate() was implicitly called", "The code does not compile because b cannot be reassigned inside an enhanced for loop", "2.0 and 5.0, unchanged, because reassigning b only points the local copy at a new object and does not affect the array"], "answer": 3, "explanation": "Assigning b = new Balloon(0.0) only makes the enhanced for loop variable b refer to a brand-new object; it does not change which object reference is stored in the balloons array, so the original Balloon objects, and their heights of 2.0 and 5.0, are unaffected (4.4.A.4, 4.4.A.5). The heights are not reset to 0.0, no inflate() call happens anywhere in this code, and reassigning the enhanced for loop variable is legal Java."},
  {"id": "4.4-intermediate-04", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] songDurations = {180, 200, 220, 240};\nfor (int i = songDurations.length / 2; i < songDurations.length; i++)\n{\n    songDurations[i] = songDurations[i] + 20;\n}\nWhat are the contents of songDurations after the code segment executes?", "choices": ["{180, 200, 240, 260}", "{200, 220, 240, 260}", "{180, 200, 220, 240}", "{200, 220, 220, 240}"], "answer": 0, "explanation": "Since songDurations.length is 4, the loop starts at index 2 and only modifies indices 2 and 3, adding 20 to each, leaving indices 0 and 1 unchanged, which produces {180, 200, 240, 260} (4.4.A.2). Adding 20 to every element ignores the starting index of 2, leaving the array completely unchanged ignores that the loop body does execute, and modifying only index 2 ignores that index 3 is also within the loop's bounds."},
  {"id": "4.4-intermediate-05", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.6", "prompt": "A student wants to set every element of an array named batteryLevels to 100. Consider the following three candidate implementations.\nI.\nfor (int i = 0; i < batteryLevels.length; i++)\n{\n    batteryLevels[i] = 100;\n}\nII.\nint i = 0;\nwhile (i < batteryLevels.length)\n{\n    batteryLevels[i] = 100;\n    i++;\n}\nIII.\nfor (int level : batteryLevels)\n{\n    level = 100;\n}\nWhich implementation(s) correctly set every element of batteryLevels to 100?", "choices": ["I only", "I and II only", "III only", "I, II, and III"], "answer": 1, "explanation": "Implementations I and II both use an index to directly assign 100 to each element, batteryLevels[i], so both correctly modify the array (4.4.A.2, 4.4.A.6). Implementation III only reassigns the enhanced for loop variable level, which is a copy, so it never changes any element actually stored in batteryLevels (4.4.A.4)."},
  {"id": "4.4-intermediate-06", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.4", "prompt": "Consider the following code segment.\nint[] rainTotals = {10, 20, 30};\nint last = -1;\nfor (int total : rainTotals)\n{\n    total = total * 2;\n    last = total;\n}\nSystem.out.println(last);\nSystem.out.println(rainTotals[2]);\nWhat is printed as a result of executing this code segment?", "choices": ["60\n60", "30\n30", "60\n30", "30\n60"], "answer": 2, "explanation": "Inside each iteration, total is doubled and stored into last, so after the final iteration last holds 30 * 2 = 60; but reassigning total never changes the array, so rainTotals[2] still holds its original value, 30 (4.4.A.4). The array element is not permanently doubled, so the second printed value cannot be 60, and last cannot equal 30 since it was assigned the doubled value on every iteration."},
  {"id": "4.4-intermediate-07", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] hikeDistances = {3, 6, 9, 12, 15};\nfor (int i = 0; i < hikeDistances.length - 2; i++)\n{\n    hikeDistances[i] = 0;\n}\nWhich elements of hikeDistances remain unchanged after this code executes?", "choices": ["hikeDistances[0] and hikeDistances[1] only", "No elements remain unchanged", "hikeDistances[4] only", "hikeDistances[3] and hikeDistances[4] only"], "answer": 3, "explanation": "Since hikeDistances.length is 5, the loop condition i < 3 means the loop only sets indices 0, 1, and 2 to 0, leaving indices 3 and 4 at their original values of 12 and 15 (4.4.A.2). Indices 0 and 1 are among those changed to 0, not left unchanged; some elements clearly remain unchanged, since the loop stops before reaching every index; and index 4 is not the only unchanged element, since index 3 is also untouched."},
  {"id": "4.4-intermediate-08", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.6", "prompt": "A programmer writes the following enhanced for loop.\nint[] fuelLevels = {8, 16, 24, 32};\nint total = 0;\nfor (int level : fuelLevels)\n{\n    total = total + level;\n}\nWhich indexed for loop is equivalent to this enhanced for loop?", "choices": ["for (int i = 0; i < fuelLevels.length; i++)\n{\n    total = total + fuelLevels[i];\n}", "for (int i = 0; i < fuelLevels.length; i++)\n{\n    total = total + i;\n}", "for (int i = 1; i <= fuelLevels.length; i++)\n{\n    total = total + fuelLevels[i];\n}", "for (int i = fuelLevels.length; i > 0; i--)\n{\n    total = total + fuelLevels[i];\n}"], "answer": 0, "explanation": "Using i to index into fuelLevels and adding fuelLevels[i] to total on every iteration from index 0 through fuelLevels.length - 1 reproduces the exact same additions as the enhanced for loop (4.4.A.6). Adding the index i itself instead of the element's value computes something entirely different, the second candidate starts at an invalid index and also runs one iteration too many, and the last candidate begins by referencing an invalid index one past the end of the array."},
  {"id": "4.4-intermediate-09", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.5", "prompt": "A Drone class is defined as follows.\npublic class Drone\n{\n    private int altitude;\n    public Drone(int startAltitude)\n    {\n        altitude = startAltitude;\n    }\n    public void ascend(int amount)\n    {\n        altitude = altitude + amount;\n    }\n    public int getAltitude()\n    {\n        return altitude;\n    }\n}\nConsider the following two code segments, each starting with the same array.\nDrone[] fleet = {new Drone(10), new Drone(20)};\nSegment 1:\nfor (Drone d : fleet)\n{\n    d.ascend(5);\n}\nSegment 2:\nfor (Drone d : fleet)\n{\n    d = new Drone(0);\n}\nWhich segment(s) change the altitude values of the Drone objects referenced by fleet?", "choices": ["Neither segment changes the altitude values", "Segment 1 only", "Segment 2 only", "Both Segment 1 and Segment 2"], "answer": 1, "explanation": "Segment 1 calls the mutator ascend() on d, which still refers to the same Drone object stored in fleet, so it genuinely changes that object's altitude (4.4.A.5). Segment 2 only reassigns the local copy d to a brand-new Drone object; it never touches the object reference actually stored in fleet, so the original altitudes are unaffected (4.4.A.4)."},
  {"id": "4.4-intermediate-10", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.3", "prompt": "Consider the following code segment.\nint[] stepCounts = {500, 1000, 1500};\nfor (int steps : stepCounts)\n{\n    steps = steps + 250;\n    stepCounts[1] = 9999;\n}\nWhat are the contents of stepCounts after this code executes?", "choices": ["{750, 1250, 1750}", "{500, 9999, 1500}, but only after the loop's second iteration", "{500, 9999, 1500}", "{750, 9999, 1750}"], "answer": 2, "explanation": "Even though steps is reassigned each iteration with no lasting effect, the separate statement stepCounts[1] = 9999 directly modifies index 1 of the array itself, and it executes on every one of the three iterations, leaving stepCounts as {500, 9999, 1500} (4.4.A.3, 4.4.A.4). No element is increased by 250, since that change only affects the copy steps, and the assignment to index 1 takes effect starting with the loop's very first iteration, not just the second."},
  {"id": "4.4-intermediate-11", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] pageViews = {5, 10, 15, 20, 25};\nint i = 1;\nwhile (i < pageViews.length - 1)\n{\n    pageViews[i] = pageViews[i] * 10;\n    i++;\n}\nWhat are the contents of pageViews after this code executes?", "choices": ["{50, 100, 150, 200, 250}", "{5, 10, 15, 20, 25}", "{5, 100, 150, 20, 25}", "{5, 100, 150, 200, 25}"], "answer": 3, "explanation": "Since pageViews.length is 5, the condition i < 4 allows the loop to run for i = 1, 2, and 3, multiplying pageViews[1], pageViews[2], and pageViews[3] by 10, while indices 0 and 4 are never accessed and stay at their original values, producing {5, 100, 150, 200, 25} (4.4.A.2). Multiplying every element ignores that the loop starts at index 1 and stops before index 4; leaving the array completely unchanged ignores that the loop body does execute; and leaving index 3 unmultiplied ignores that i = 3 still satisfies the loop condition i < 4."},
  {"id": "4.4-intermediate-12", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.6", "prompt": "A student is traversing an array named ratings and needs to modify each element based on the value of the previous element, using an expression like ratings[i] = ratings[i - 1] + ratings[i]. Which statement about rewriting this traversal as an enhanced for loop is correct?", "choices": ["This traversal cannot be directly rewritten as an enhanced for loop, because the enhanced for loop variable does not provide access to the index needed to reference the previous element", "This traversal can be directly rewritten as an enhanced for loop by simply replacing ratings[i] with the enhanced for loop variable", "This traversal can be rewritten as an enhanced for loop as long as the loop variable is declared as a class variable", "This traversal cannot be written using any loop, indexed or enhanced, because it depends on a previous element"], "answer": 0, "explanation": "Because this traversal needs the numeric index i to reference the previous element, ratings[i - 1], and the enhanced for loop variable provides no access to any index at all, this traversal cannot be directly rewritten using an enhanced for loop (4.4.A.6, 4.4.A.3). Simply substituting the loop variable does not provide access to a previous element, declaring the variable as a class variable does not grant index access either, and an indexed for loop or while loop can correctly perform this traversal, so it is not impossible with every loop type."},
  {"id": "4.4-intermediate-13", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.4", "prompt": "A student writes two versions of code intended to add 10 to every element of an array named boxWeights, which initially contains {5, 15, 25}.\nVersion 1:\nfor (int w : boxWeights)\n{\n    w = w + 10;\n}\nVersion 2:\nfor (int i = 0; i < boxWeights.length; i++)\n{\n    boxWeights[i] = boxWeights[i] + 10;\n}\nWhat are the contents of boxWeights after each version executes, assuming each version starts from the original array?", "choices": ["Version 1 produces {15, 25, 35}; Version 2 produces {5, 15, 25}", "Version 1 produces {5, 15, 25}; Version 2 produces {15, 25, 35}", "Both versions produce {15, 25, 35}", "Both versions produce {5, 15, 25}"], "answer": 1, "explanation": "Version 1 only reassigns the enhanced for loop variable w, a copy, so boxWeights is left unchanged at {5, 15, 25}; Version 2 directly assigns boxWeights[i], modifying the actual array elements to produce {15, 25, 35} (4.4.A.4). The two versions do not behave identically, since only the indexed version can modify the array's contents through direct index access."},
  {"id": "4.4-intermediate-14", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.5", "prompt": "Using the Drone class from an earlier problem, consider the following code segment.\nDrone[] fleet = {new Drone(10), new Drone(20), new Drone(30)};\nfor (Drone d : fleet)\n{\n    if (d.getAltitude() < 25)\n    {\n        d.ascend(100);\n    }\n}\nWhat are the altitude values of the Drone objects referenced by fleet after this code executes?", "choices": ["10, 20, and 30, unchanged", "110, 120, and 130", "110, 120, and 30", "The code does not compile because d cannot call getAltitude() inside a condition"], "answer": 2, "explanation": "The condition checks each Drone's current altitude, and only the first two Drones, with altitudes 10 and 20, are below 25, so ascend(100) is called only on those two objects, giving 110, 120, and 30 (4.4.A.5). The altitudes are not left unchanged, since ascend() does execute for two of the three Drones; the third Drone's altitude of 30 does not increase, since 30 is not less than 25; and calling an accessor method like getAltitude() inside a condition is valid, compiling code."},
  {"id": "4.4-intermediate-15", "course": "csa", "topic": "4.4", "tier": "intermediate", "lo": "4.4.A.2", "prompt": "A student is deciding among three candidate for loop headers intended to correctly traverse every element of an array named voteTallies without causing an exception.\nI. for (int i = 0; i <= voteTallies.length; i++)\nII. for (int i = 0; i < voteTallies.length; i++)\nIII. for (int i = -1; i < voteTallies.length; i++)\nWhich of these loop headers, if used to access voteTallies[i] in the loop body, would run without throwing an ArrayIndexOutOfBoundsException?", "choices": ["I only", "I and III only", "III only", "II only"], "answer": 3, "explanation": "Only header II keeps i strictly less than voteTallies.length, which stays within the valid index range of 0 through voteTallies.length - 1 for every iteration (4.4.A.2). Header I uses <=, allowing i to reach the invalid index voteTallies.length on its final iteration, and header III starts at i = -1, which is an invalid index on its very first iteration."},
  {"id": "4.4-complex-01", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "Consider the following code segment, which is intended to print every element of an array named ticketPrices.\nint[] ticketPrices = {12, 18, 24, 30};\nfor (int i = 0; i <= ticketPrices.length; i++)\n{\n    System.out.println(ticketPrices[i]);\n}\nWhich change corrects the code so that it prints every element without throwing an exception?", "choices": ["Change the initial value of i to 1", "Change the array declaration to int[] ticketPrices = new int[5];", "Change the loop condition to i < ticketPrices.length", "Change ticketPrices[i] to ticketPrices[i + 1]"], "answer": 2, "explanation": "The loop condition i <= ticketPrices.length allows i to reach the invalid index ticketPrices.length on its final iteration, causing an ArrayIndexOutOfBoundsException; changing the condition to i < ticketPrices.length keeps i within the valid range of 0 through ticketPrices.length - 1 (4.4.A.2). Starting at i = 1 would skip the first element and still throw the same exception at the end, resizing the array only delays the exception rather than fixing the underlying off-by-one error, and referencing ticketPrices[i + 1] would only make the invalid access happen even sooner."},
  {"id": "4.4-complex-02", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "A student writes the following method intended to double every element of an array named coinValues.\npublic static void doubleAll(int[] coinValues)\n{\n    int i = 0;\n    while (i < coinValues.length)\n    {\n        coinValues[i] = coinValues[i] * 2;\n    }\n}\nWhat is the most likely result of calling this method?", "choices": ["The method correctly doubles every element of coinValues", "The method doubles only the first element of coinValues", "The method throws an ArrayIndexOutOfBoundsException", "The method never terminates, because i is never incremented inside the loop"], "answer": 3, "explanation": "Because the loop body never updates i, the condition i < coinValues.length remains true forever, so the loop repeatedly doubles coinValues[0] and never terminates (4.4.A.2). The method does not correctly and fully traverse the array, since it never advances past index 0, and no exception occurs because i itself never changes to an invalid value; the program simply runs forever."},
  {"id": "4.4-complex-03", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "A student writes the following code segment, intended to fill the array runningTotals so that each element (after the first two) equals the sum of the two elements before it.\nint[] runningTotals = new int[8];\nrunningTotals[0] = 1;\nrunningTotals[1] = 1;\nfor (int j = 0; j < runningTotals.length; j++)\n{\n    runningTotals[j] = runningTotals[j - 2] + runningTotals[j - 1];\n}\nWhich change corrects the code so that it works as intended without throwing an exception?", "choices": ["Change the initial value of j in the for loop header to 2", "Change the loop condition to j <= runningTotals.length", "Change runningTotals[j - 2] to runningTotals[j + 2]", "Change runningTotals[0] and runningTotals[1] to be assigned inside the loop instead of before it"], "answer": 0, "explanation": "Starting j at 0 causes the first iteration to reference runningTotals[-2] and runningTotals[-1], both invalid indices, throwing an ArrayIndexOutOfBoundsException; starting j at 2 preserves the two seed values already stored at indices 0 and 1 and begins computation only once both runningTotals[j - 2] and runningTotals[j - 1] refer to valid, already-filled indices (4.4.A.2). Changing the condition to <= only adds an additional invalid access at the end without fixing the invalid access at the start, referencing runningTotals[j + 2] would reference unfilled or invalid future indices, and moving the seed assignments inside the loop does not resolve the invalid negative indices on the first iterations."},
  {"id": "4.4-complex-04", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.6", "prompt": "A student wants to fill an array named ratings, of length 5, so that it contains {2, 4, 6, 8, 10}. The student considers four candidate code segments to replace /* code */ below.\nint[] ratings = new int[5];\n/* code */\nI.\nfor (int j = 0; j < ratings.length; j++)\n{\n    ratings[j] = (j + 1) * 2;\n}\nII.\nint x = 2;\nfor (int r : ratings)\n{\n    r = x;\n    x += 2;\n}\nIII.\nratings[0] = 2;\nfor (int j = 1; j < ratings.length; j++)\n{\n    ratings[j] = ratings[j - 1] + 1;\n}\nIV.\nratings[4] = 10;\nfor (int j = ratings.length - 1; j > 0; j--)\n{\n    ratings[j - 1] = ratings[j] - 2;\n}\nWhich candidate(s) correctly set ratings to {2, 4, 6, 8, 10}?", "choices": ["IV only", "I and IV only", "II only", "I, II, and III"], "answer": 1, "explanation": "Candidate I directly computes ratings[j] = (j + 1) * 2 for every index, producing {2, 4, 6, 8, 10}, and candidate IV correctly fills the array from the last index backward, each element 2 less than its successor, also producing {2, 4, 6, 8, 10} (4.4.A.2, 4.4.A.6). Candidate II only reassigns the enhanced for loop variable r, leaving every element at its default value of 0 (4.4.A.4), and candidate III adds 1 instead of 2 at each step, producing {2, 3, 4, 5, 6} instead of the intended array."},
  {"id": "4.4-complex-05", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.5", "prompt": "Using the Player class defined below,\npublic class Player\n{\n    private int score;\n    public Player(int startScore)\n    {\n        score = startScore;\n    }\n    public void addPoints(int amount)\n    {\n        score = score + amount;\n    }\n    public int getScore()\n    {\n        return score;\n    }\n}\nconsider the following code segment.\nPlayer[] roster = {new Player(10), new Player(20), new Player(30)};\nfor (Player p : roster)\n{\n    p.addPoints(5);\n    p = new Player(0);\n}\nWhat are the score values of the Player objects referenced by roster after this code executes?", "choices": ["0, 0, and 0, because p was reassigned to a new Player on every iteration", "10, 20, and 30, unchanged, because p was eventually reassigned away from the original objects", "15, 25, and 35, because addPoints(5) modifies each original object before p is reassigned", "The code does not compile because p cannot be reassigned after calling a method on it"], "answer": 2, "explanation": "On each iteration, addPoints(5) is called first, genuinely modifying the score of the object that p currently refers to, which is the same object stored in roster; only afterward is p reassigned to a new, separate Player object, which has no effect on roster at all, leaving the final scores at 15, 25, and 35 (4.4.A.5, 4.4.A.4). The scores are not reset to 0 or left completely unchanged, since the mutator call happens before the reassignment every time, and reassigning an enhanced for loop variable after calling a method on it is entirely legal, compiling code."},
  {"id": "4.4-complex-06", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.6", "prompt": "A student writes the following enhanced for loop, which is intended to set every element of an array named ratings to double its original value.\nint[] ratings = {3, 6, 9};\nfor (int r : ratings)\n{\n    r = r * 2;\n}\nA classmate claims this loop can be rewritten as an equivalent indexed for loop simply by replacing the enhanced for header with a standard indexed for loop header, while keeping the same style of assignment. Which statement best evaluates this claim?", "choices": ["The claim is correct, since ratings[i] = r * 2 in an indexed for loop would behave identically", "The claim is correct, since any enhanced for loop can always be rewritten with identical assignment statements, only the header needs to change", "The claim is incorrect, because an indexed for loop cannot access the elements of ratings at all", "The claim is incorrect, because the enhanced for loop never actually modifies ratings, while an indexed for loop using ratings[i] = ratings[i] * 2 would; the two are not equivalent unless the assignment target is changed to the array element itself"], "answer": 3, "explanation": "The original enhanced for loop only reassigns the copy r and has no effect on ratings (4.4.A.4), so simply swapping in an indexed for loop header while keeping an assignment like r = r * 2 would not reproduce that (already ineffective) behavior correctly, and the classmate's implied intent, actually doubling the array, requires assigning to ratings[i] directly, not just changing the header (4.4.A.6). An indexed for loop can access every element of ratings through ratings[i], so that is not the issue, and not every enhanced for loop and indexed for loop pair are automatically equivalent just by changing the header, since the assignment target matters too."},
  {"id": "4.4-complex-07", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "Consider the following code segment, which traverses, in parallel, two arrays of equal length, dailySales and weeklyGoals. The code is intended to replace each element of weeklyGoals with the larger of the two corresponding elements, while leaving dailySales unchanged.\nfor (int i = 0; i < dailySales.length; i++)\n{\n    if (dailySales[i] > weeklyGoals[i])\n    {\n        dailySales[i] = weeklyGoals[i];\n    }\n    else\n    {\n        weeklyGoals[i] = dailySales[i];\n    }\n}\nWhich revision corrects the code so that it meets the stated goal?", "choices": ["Replace the body of the if block with weeklyGoals[i] = dailySales[i]; and delete the else block entirely", "Change the relational operator in the if condition to <", "Swap the two array names, dailySales and weeklyGoals, everywhere they appear", "Change the loop condition to i <= dailySales.length"], "answer": 0, "explanation": "The corrected logic should always assign weeklyGoals[i] = dailySales[i] whenever dailySales[i] is greater, with no else branch needed, since weeklyGoals[i] already holds the correct value otherwise; removing the else block prevents the current code from incorrectly overwriting dailySales (4.4.A.2). Simply flipping the relational operator swaps which array gets modified but still incorrectly modifies dailySales in some cases, swapping the array names does not fix the underlying assignment direction, and changing the loop bound to <= would only introduce an ArrayIndexOutOfBoundsException without addressing the assignment logic."},
  {"id": "4.4-complex-08", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "Consider the following code segment.\nint[] pointTotals = {4, 8, 12, 16, 20};\nfor (int x = pointTotals.length - 1; x > 0; x--)\n{\n    pointTotals[x - 1] = pointTotals[x] + pointTotals[x - 1];\n}\nWhat are the contents of pointTotals after this code executes?", "choices": ["{4, 8, 12, 16, 20}", "{60, 56, 48, 36, 20}", "{20, 16, 12, 8, 4}", "{24, 28, 32, 36, 20}"], "answer": 1, "explanation": "Starting at x = 4 and decreasing, the loop repeatedly adds the element at x into the element before it: pointTotals[3] becomes 16 + 20 = 36, then pointTotals[2] becomes 12 + 36 = 48, then pointTotals[1] becomes 8 + 48 = 56, then pointTotals[0] becomes 4 + 56 = 60, producing {60, 56, 48, 36, 20} (4.4.A.2). The array is not left unchanged, since the loop body executes for every value of x from 4 down to 1; simply reversing the original array ignores the accumulation performed by the addition; and adding a constant offset to each element does not reflect the actual running accumulation the loop performs."},
  {"id": "4.4-complex-09", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "Consider the following method.\npublic static void copySecondHalf(int[] source, int[] destination)\n{\n    for (int i = source.length / 2; i < source.length; i++)\n    {\n        destination[i] = source[i];\n    }\n}\nAssume source and destination both have length 6, source contains {1, 2, 3, 4, 5, 6}, and destination initially contains {0, 0, 0, 0, 0, 0}. What are the contents of destination after copySecondHalf(source, destination) executes?", "choices": ["{1, 2, 3, 4, 5, 6}", "{0, 0, 0, 4, 5, 6}, but only after the loop's final iteration", "{0, 0, 0, 4, 5, 6}", "{4, 5, 6, 0, 0, 0}"], "answer": 2, "explanation": "Since source.length is 6, the loop starts at index 3 and copies only indices 3, 4, and 5 from source into destination, leaving destination's first three elements at their original value of 0, producing {0, 0, 0, 4, 5, 6} (4.4.A.2). The full array is not copied, since the loop never touches indices 0 through 2; the result is established after the entire loop finishes, not only visible after the last iteration; and the copied values are not shifted to the front of destination, since each value is placed at its own matching index i."},
  {"id": "4.4-complex-10", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "Consider the following code segment, where limit is an int variable and dataPoints is an int array, both with unknown values.\nfor (int i = 1; i < limit; i++)\n{\n    if (dataPoints[i] > 0)\n    {\n        System.out.print(\"FOUND\");\n    }\n}\nWhat is the maximum number of times that \"FOUND\" could possibly be printed?", "choices": ["limit", "dataPoints.length", "limit + 1", "limit - 1"], "answer": 3, "explanation": "The loop body executes once for each value of i from 1 up to, but not including, limit, which is limit - 1 total iterations; since \"FOUND\" prints at most once per iteration, when every accessed element happens to be positive, the maximum possible number of times it prints is limit - 1 (4.4.A.2). The loop does not run limit times, since it starts at 1 rather than 0, it does not run limit + 1 times since the condition uses a strict less-than, and the number of iterations is governed by limit, not directly by dataPoints.length, which is not given to be equal to limit."},
  {"id": "4.4-complex-11", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.5", "prompt": "Using the Player class defined earlier, a student considers four candidate code segments, each starting from roster = {new Player(10), new Player(20)}.\nI.\nfor (Player p : roster)\n{\n    p.addPoints(10);\n}\nII.\nfor (Player p : roster)\n{\n    p = new Player(100);\n}\nIII.\nfor (int i = 0; i < roster.length; i++)\n{\n    roster[i] = new Player(100);\n}\nIV.\nfor (int i = 0; i < roster.length; i++)\n{\n    roster[i].addPoints(10);\n}\nWhich candidate(s) result in the Player objects referenced by roster having scores of 20 and 30?", "choices": ["I and IV only", "II and III only", "I, III, and IV only", "I, II, III, and IV"], "answer": 0, "explanation": "Candidates I and IV both call the mutator addPoints(10) on the actual objects referenced by roster, whether through the enhanced for loop variable p or directly through roster[i], correctly producing scores of 20 and 30 (4.4.A.5). Candidate II only reassigns the local copy p to a brand-new object and never affects roster (4.4.A.4), while candidate III directly replaces the object references stored in roster with new Player(100) objects, which changes the scores to 100 and 100 rather than 20 and 30."},
  {"id": "4.4-complex-12", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.6", "prompt": "A student wants to subtract 3 from every element of an array named tempsF, which contains {80, 85, 90}. Four candidate implementations are proposed.\nI.\nfor (int i = 0; i < tempsF.length; i++)\n{\n    tempsF[i] = tempsF[i] - 3;\n}\nII.\nint i = 0;\nwhile (i < tempsF.length)\n{\n    tempsF[i] -= 3;\n    i++;\n}\nIII.\nfor (int t : tempsF)\n{\n    t -= 3;\n}\nIV.\nfor (int i = tempsF.length - 1; i >= 0; i--)\n{\n    tempsF[i] = tempsF[i] - 3;\n}\nWhich implementation(s) correctly produce {77, 82, 87}?", "choices": ["I only", "I, II, and IV only", "III only", "I, II, III, and IV"], "answer": 1, "explanation": "Implementations I, II, and IV all directly assign each array element through its index, whether traversing forward or backward, so all three correctly subtract 3 from every element (4.4.A.2, 4.4.A.6). Implementation III only modifies the enhanced for loop variable t, a copy, so it has no effect on the actual elements stored in tempsF (4.4.A.4)."},
  {"id": "4.4-complex-13", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.2", "prompt": "A student writes the following method intended to add 1 to every element of an array named visitCounts.\npublic static void incrementAll(int[] visitCounts)\n{\n    int i = 0;\n    while (i < visitCounts.length)\n    {\n        visitCounts[i] = visitCounts[i] + 1;\n        i = i;\n    }\n}\nWhat is the most likely result of calling this method?", "choices": ["The method correctly adds 1 to every element of visitCounts", "The method throws an ArrayIndexOutOfBoundsException", "The method never terminates, because i = i does not change the value of i", "The method adds 1 to every element except the last one"], "answer": 2, "explanation": "The statement i = i assigns i's current value back to itself, so i never actually advances, meaning the while condition i < visitCounts.length remains true forever and the loop repeatedly modifies only visitCounts[0] without end (4.4.A.2). The method does not correctly traverse the whole array, since it never reaches any index beyond 0; no exception is thrown, since i itself never becomes invalid; and the loop does not simply stop one element early, it never terminates at all."},
  {"id": "4.4-complex-14", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.3", "prompt": "Consider the following code segment.\nint[] rainTotals = {3, 5, 7, 9};\nint days = 0;\nint bonus = 2;\nfor (int total : rainTotals)\n{\n    days = days + bonus;\n}\nSystem.out.println(days);\nWhat is printed as a result of executing this code segment?", "choices": ["24, because each element of rainTotals is added to days along with the bonus", "2, because the loop only executes once", "0, because the enhanced for loop variable total is never used, so the loop has no effect", "8, because bonus is added to days once for each of the four elements in rainTotals"], "answer": 3, "explanation": "The enhanced for loop runs once for every element in rainTotals, which has four elements, and each iteration adds the fixed value bonus, not any element's actual value, to days, producing 2 + 2 + 2 + 2 = 8 (4.4.A.3). The elements of rainTotals themselves are never added to days, so 24 is incorrect; the loop executes four times, not once; and even though total's value is never read, the loop body still executes once per element, so days is not left at 0."},
  {"id": "4.4-complex-15", "course": "csa", "topic": "4.4", "tier": "complex", "lo": "4.4.A.6", "prompt": "A student writes the following code segment.\nint[] entries = {10, 20, 30, 40};\nfor (int i = 0; i < entries.length - 1; i++)\n{\n    entries[i] = entries[i + 1];\n}\nA classmate suggests this loop can be rewritten as an equivalent enhanced for loop. Which statement best evaluates this suggestion?", "choices": ["The suggestion is incorrect, because the loop body references entries[i + 1], which depends on the index i; the enhanced for loop variable never provides access to any index, so this traversal cannot be directly rewritten as an enhanced for loop", "The suggestion is correct, since replacing entries[i] and entries[i + 1] with the enhanced for loop variable produces identical behavior", "The suggestion is correct, as long as the array is traversed in reverse order using the enhanced for loop", "The suggestion is incorrect, because enhanced for loops cannot be used with int arrays"], "answer": 0, "explanation": "Because each iteration needs to reference the next element using the index expression i + 1, and the enhanced for loop variable never exposes any index, this shifting traversal cannot be directly rewritten using an enhanced for loop; an indexed for loop or while loop is required instead (4.4.A.6, 4.4.A.3). Simply substituting the loop variable would not provide access to a different index's element, reversing the traversal order does not solve the fundamental lack of index access, and enhanced for loops work perfectly well with int arrays in general."},
  {"id": "4.5-basic-01", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A student writes a method to find the largest value in an array of daily high temperatures, temps.\npublic static int findMax(int[] temps)\n{\n    int max = temps[0];\n    for (int i = 1; i < temps.length; i++)\n    {\n        if (temps[i] > max)\n        {\n            max = temps[i];\n        }\n    }\n    return max;\n}\nWhat value is returned when findMax is called on the array {68, 74, 71, 80, 77}?", "choices": ["80", "68", "74", "77"], "answer": 0, "explanation": "The method implements the standard maximum-value algorithm (4.5.A.1): max starts at the first element and is updated whenever a larger element is found while traversing the rest of the array. Tracing the array shows max becomes 74 and then 80, and no later element exceeds 80, so 80 is returned. 68 is only the initial value, 74 is an intermediate maximum that gets overwritten, and 77 is smaller than the true maximum so it is never stored in max."},
  {"id": "4.5-basic-02", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A student wants to write a method that returns the smallest value in an array of test scores named scores, where scores is guaranteed to have at least one element. Which implementation correctly finds the minimum value using the standard minimum-value algorithm?", "choices": ["int min = 0;\nfor (int i = 0; i < scores.length; i++)\n{\n    if (scores[i] < min)\n    {\n        min = scores[i];\n    }\n}\nreturn min;", "int min = scores[0];\nfor (int i = 1; i < scores.length; i++)\n{\n    if (scores[i] < min)\n    {\n        min = scores[i];\n    }\n}\nreturn min;", "int min = scores[0];\nfor (int i = 1; i < scores.length; i++)\n{\n    if (scores[i] > min)\n    {\n        min = scores[i];\n    }\n}\nreturn min;", "int min = scores[0];\nfor (int i = 1; i < scores.length; i++)\n{\n    if (scores[i] < min)\n    {\n        min = scores[i];\n    }\n}\nreturn scores[0];"], "answer": 1, "explanation": "The correct minimum-value algorithm (4.5.A.1) initializes min to the first element and updates it only when a smaller element is found. Initializing min to 0 fails whenever every score is greater than 0, since min would incorrectly stay at 0 the whole time. Using a greater-than comparison finds the maximum instead of the minimum, and always returning scores[0] ignores the loop entirely and reports the wrong value whenever the first element is not actually the smallest."},
  {"id": "4.5-basic-03", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A store's daily sales, in dollars, are stored in the array sales. A method computes the total sales.\npublic static double totalSales(double[] sales)\n{\n    double sum = 0;\n    for (int i = 0; i < sales.length; i++)\n    {\n        sum = sum + sales[i];\n    }\n    return sum;\n}\nWhat value is returned when totalSales is called on the array {120.0, 85.5, 60.0}?", "choices": ["205.5", "60.0", "265.5", "120.0"], "answer": 2, "explanation": "This method correctly implements the standard sum algorithm (4.5.A.1): sum starts at 0 and accumulates every element of sales, giving 120.0 + 85.5 + 60.0 = 265.5. 205.5 results from stopping the accumulation one element early, 60.0 is only the last element, and 120.0 is only the first element, neither of which reflects a full traversal."},
  {"id": "4.5-basic-04", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method is intended to compute the average of the elements in an int array called readings.\npublic static double average(int[] readings)\n{\n    int sum = 0;\n    for (int i = 0; i < readings.length; i++)\n    {\n        sum = sum + readings[i];\n    }\n    return sum / readings.length;\n}\nWhat is the most significant problem with this implementation of the compute-an-average algorithm?", "choices": ["The loop does not visit every element of readings, so the sum is incomplete.", "The variable sum is never reset to 0 before the loop begins.", "The return type double is incompatible with the int variable sum, so the method will not compile.", "Because sum and readings.length are both int, integer division may truncate the result instead of producing an accurate decimal average."], "answer": 3, "explanation": "Even though the sum is accumulated correctly across the whole array, sum / readings.length divides one int by another, performing integer division that truncates any fractional part before the result is ever widened to double (4.5.A.1, sum/average algorithm). The loop does visit every index from 0 to readings.length - 1, sum is properly initialized to 0 as a local variable, and an int value can be returned from a method declared double without a compile error because it is automatically widened."},
  {"id": "4.5-basic-05", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "An array of ints named balances represents customer account balances. A method should determine whether at least one balance is negative.\npublic static boolean hasNegative(int[] balances)\n{\n    boolean found = false;\n    for (int i = 0; i < balances.length; i++)\n    {\n        if (balances[i] < 0)\n        {\n            found = true;\n        }\n    }\n    return found;\n}\nWhich standard array algorithm does this method correctly implement?", "choices": ["Determining if all elements have a particular property", "Determining if at least one element has a particular property", "Counting the number of elements with a particular property", "Determining the minimum value in the array"], "answer": 1, "explanation": "found is set to true whenever any single balance is negative and is never reset back to false, so it correctly reports whether at least one element has the property of being negative (4.5.A.1). Determining if all elements share a property would require the check to fail as soon as one element does not qualify, counting would require a numeric counter rather than a boolean, and finding a minimum would require tracking the smallest numeric value rather than a true/false condition."},
  {"id": "4.5-basic-06", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method traverses an array of exam scores named scores to determine if any score is below 60.\npublic static boolean anyFailing(int[] scores)\n{\n    for (int i = 0; i < scores.length; i++)\n    {\n        if (scores[i] < 60)\n        {\n            return true;\n        }\n    }\n    return false;\n}\nWhat does anyFailing return when it is called on the array {75, 82, 58, 91}?", "choices": ["false", "An ArrayIndexOutOfBoundsException is thrown", "true", "The method does not compile"], "answer": 2, "explanation": "This is the standard at-least-one-element algorithm implemented with an early return (4.5.A.1): as soon as an element under 60 is found, the method exits with true. Since 58 is less than 60, the method returns true at index 2 and never reaches the final return false; every index accessed is within bounds, so no exception occurs, and the method compiles without issue."},
  {"id": "4.5-basic-07", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method should determine whether every element in an array of ints named ages is at least 18.\npublic static boolean allAdults(int[] ages)\n{\n    for (int i = 0; i < ages.length; i++)\n    {\n        if (ages[i] < 18)\n        {\n            return false;\n        }\n    }\n    return true;\n}\nWhich standard array algorithm does allAdults implement?", "choices": ["Determining if at least one element has a particular property", "Shifting the elements of the array", "Computing the average of the elements", "Determining if all elements have a particular property"], "answer": 3, "explanation": "The method exits immediately with false the moment any single element fails the age-18 test, and only returns true after every element has passed, which is exactly the standard all-elements algorithm (4.5.A.1). It does not test for a single matching element (which would return true immediately upon success rather than false), and it neither shifts data nor computes any numeric total."},
  {"id": "4.5-basic-08", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method checks whether every element of an int array named codes is even.\npublic static boolean allEven(int[] codes)\n{\n    for (int i = 0; i < codes.length; i++)\n    {\n        if (codes[i] % 2 != 0)\n        {\n            return false;\n        }\n    }\n    return true;\n}\nWhat is returned when allEven is called on the array {4, 8, 10, 7, 12}?", "choices": ["false", "true", "12", "7"], "answer": 0, "explanation": "This is the standard all-elements algorithm (4.5.A.1): the method returns false as soon as an odd element is found. Since 7 at index 3 is odd, codes[3] % 2 != 0 is true and the method immediately returns false without examining 12. Returning true would require every element to be even, and 12 and 7 are array values, not the boolean result the method actually returns."},
  {"id": "4.5-basic-09", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "An array of doubles named prices stores item prices. A method counts how many prices are at least $50.00.\npublic static int countExpensive(double[] prices)\n{\n    int count = 0;\n    for (int i = 0; i < prices.length; i++)\n    {\n        if (prices[i] >= 50.00)\n        {\n            count++;\n        }\n    }\n    return count;\n}\nWhat value is returned when countExpensive is called on the array {45.00, 50.00, 62.50, 30.00, 99.99}?", "choices": ["2", "4", "3", "5"], "answer": 2, "explanation": "This method implements the standard counting algorithm (4.5.A.1): count increases only for elements at least 50.00. Exactly three elements, 50.00, 62.50, and 99.99, satisfy the condition, so 3 is returned. 2 undercounts by missing one qualifying element, 4 overcounts by including a value below the threshold, and 5 would only be correct if every element in the array qualified."},
  {"id": "4.5-basic-10", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "An array of Strings named words stores a list of words. A method counts how many words begin with the letter \"A\".\npublic static int countAWords(String[] words)\n{\n    int count = 0;\n    for (int i = 0; i < words.length; i++)\n    {\n        if (words[i].charAt(0) == 'A')\n        {\n            count++;\n        }\n    }\n    return count;\n}\nWhich standard array algorithm does countAWords implement?", "choices": ["Determining if all elements have a particular property", "Accessing all consecutive pairs of elements", "Reversing the order of the elements", "Determining the number of elements having a particular property"], "answer": 3, "explanation": "A counter is incremented once for every element that satisfies a property, in this case starting with the letter A, which is exactly the standard counting algorithm (4.5.A.1). This method never returns early based on all elements passing, never accesses two indices in the same iteration, and never reorders or writes back into the array, so it does not match the all-elements, consecutive-pairs, or reversal algorithms."},
  {"id": "4.5-basic-11", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "An array of ints named temps stores hourly temperature readings. A method counts how many times the temperature increased from one hour to the next, that is, how many consecutive pairs have a later value greater than the earlier one.\npublic static int countIncreases(int[] temps)\n{\n    int count = 0;\n    for (int i = 0; i < temps.length - 1; i++)\n    {\n        if (temps[i + 1] > temps[i])\n        {\n            count++;\n        }\n    }\n    return count;\n}\nWhat value is returned when countIncreases is called on the array {60, 65, 63, 70, 72}?", "choices": ["3", "2", "4", "1"], "answer": 0, "explanation": "This method implements the standard consecutive-pairs algorithm (4.5.A.1): the loop bound temps.length - 1 keeps temps[i + 1] safely in bounds while comparing every adjacent pair. The pairs (60, 65), (63, 70), and (70, 72) each increase, giving a count of 3; the pair (65, 63) decreases and is correctly not counted. 2 and 1 undercount the true number of increasing pairs, and 4 would only occur if the decreasing pair were mistakenly counted as well."},
  {"id": "4.5-basic-12", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method should determine whether an array of ints named codes contains any duplicate values, using a nested loop.\npublic static boolean hasDuplicate(int[] codes)\n{\n    for (int i = 0; i < codes.length; i++)\n    {\n        for (int j = i + 1; j < codes.length; j++)\n        {\n            if (codes[i] == codes[j])\n            {\n                return true;\n            }\n        }\n    }\n    return false;\n}\nWhat is returned when hasDuplicate is called on the array {14, 22, 35, 22, 8}?", "choices": ["false", "true", "22", "An ArrayIndexOutOfBoundsException is thrown"], "answer": 1, "explanation": "This is the standard duplicate-detection algorithm (4.5.A.1): the inner loop starts at i + 1 so each pair of indices is compared exactly once without ever comparing an element to itself. Since codes[1] and codes[3] both equal 22, the method returns true as soon as that match is found. No exception occurs because j never reaches codes.length, and 22 is a value in the array, not the boolean the method actually returns."},
  {"id": "4.5-basic-13", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method shifts every element of an int array named data one position to the left, discarding the original first element and placing a 0 in the last position.\npublic static void shiftLeft(int[] data)\n{\n    for (int i = 0; i < data.length - 1; i++)\n    {\n        data[i] = data[i + 1];\n    }\n    data[data.length - 1] = 0;\n}\nWhat are the contents of data after shiftLeft is called on the array {3, 6, 9, 12}?", "choices": ["{0, 3, 6, 9}", "{6, 9, 12, 3}", "{3, 6, 9, 12}", "{6, 9, 12, 0}"], "answer": 3, "explanation": "This is the standard shift-left algorithm (4.5.A.1): each element moves one position toward index 0 by copying data[i + 1] into data[i], and the vacated last position is filled with 0. Tracing the array gives {6, 9, 12, 0}. {0, 3, 6, 9} describes a shift to the right instead, {6, 9, 12, 3} describes a rotation where the first element wraps to the end rather than being discarded, and {3, 6, 9, 12} is the unshifted original array."},
  {"id": "4.5-basic-14", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method is intended to rotate the elements of an int array named queue one position to the right, so the last element wraps around to become the new first element. For example, {1, 2, 3, 4} should become {4, 1, 2, 3}. Which standard array algorithm category does this describe?", "choices": ["Shifting or rotating elements", "Determining a minimum or maximum value", "Determining the presence of duplicate elements", "Computing a sum or average"], "answer": 0, "explanation": "Moving every element to an adjacent position, with the displaced element wrapping around to the opposite end, is the standard shift-or-rotate algorithm described in 4.5.A.1. No comparison for a largest or smallest value occurs, no elements are checked against each other for equality, and no numeric total is being accumulated, so the other three algorithm types do not apply here."},
  {"id": "4.5-basic-15", "course": "csa", "topic": "4.5", "tier": "basic", "lo": "4.5.A.1", "prompt": "A method reverses the order of the elements in an int array named list.\npublic static void reverseList(int[] list)\n{\n    int[] copy = new int[list.length];\n    for (int i = 0; i < list.length; i++)\n    {\n        copy[i] = list[list.length - 1 - i];\n    }\n    for (int i = 0; i < list.length; i++)\n    {\n        list[i] = copy[i];\n    }\n}\nWhat are the contents of list after reverseList is called on the array {2, 4, 6, 8}?", "choices": ["{2, 4, 6, 8}", "{8, 6, 4, 2}", "{6, 4, 2, 8}", "{8, 4, 6, 2}"], "answer": 1, "explanation": "This is the standard reverse algorithm (4.5.A.1) implemented with an auxiliary array: the first loop copies list[list.length - 1 - i] into copy[i], correctly pairing index 0 with the last element and index list.length - 1 with the first, and the second loop copies that reversed order back into list. Tracing the array produces {8, 6, 4, 2}. {2, 4, 6, 8} is the unreversed original, and the remaining two options do not correspond to a correct full reversal of every element."},
  {"id": "4.5-intermediate-01", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to return the index of the largest value in an array of ints named data.\npublic static int indexOfMax(int[] data)\n{\n    int maxIndex = 0;\n    for (int i = 0; i < data.length; i++)\n    {\n        if (data[i] > maxIndex)\n        {\n            maxIndex = i;\n        }\n    }\n    return maxIndex;\n}\nThe method does not always work as intended. What is the error?", "choices": ["The loop should start at i = 1 instead of i = 0.", "maxIndex should be initialized to data.length - 1 instead of 0.", "The comparison data[i] > maxIndex compares an array value to an index; it should instead compare data[i] to data[maxIndex].", "The method should return data[maxIndex] instead of maxIndex."], "answer": 2, "explanation": "The bug is that data[i] > maxIndex compares an element's value against an index rather than against the value currently considered largest; the comparison should be data[i] > data[maxIndex] (4.5.A.1, determining a maximum). Starting the loop at i = 1 would not fix the flawed comparison, initializing maxIndex to data.length - 1 does not address the comparison error either, and the method is intentionally designed to return an index rather than a value, so returning data[maxIndex] would change its purpose rather than fix the underlying bug."},
  {"id": "4.5-intermediate-02", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Two students each write a method intended to return the smallest value in an int array named values, which is guaranteed to contain at least one element.\nImplementation 1\nint min = values[0];\nfor (int i = 0; i < values.length; i++)\n{\n    if (values[i] < min)\n    {\n        min = values[i];\n    }\n}\nreturn min;\nImplementation 2\nint min = values[0];\nfor (int i = 1; i < values.length; i++)\n{\n    if (values[i] < min)\n    {\n        min = values[i];\n    }\n}\nreturn min;\nWhich statement best compares the two implementations?", "choices": ["Both implementations correctly return the minimum value; Implementation 2 avoids one redundant, harmless comparison of values[0] to itself.", "Implementation 1 will throw an ArrayIndexOutOfBoundsException, but Implementation 2 will not.", "Implementation 2 will return an incorrect result because it skips index 0 entirely.", "Implementation 1 is correct, but Implementation 2 will always return values[0] regardless of the rest of the array."], "answer": 0, "explanation": "Both implementations correctly compute the minimum value (4.5.A.1); Implementation 1 simply performs one extra, harmless comparison of values[0] against itself at i = 0, since min is already values[0]. Neither implementation accesses an out-of-bounds index, Implementation 2 still uses values[0] as the correct starting value for min even though the loop begins at i = 1, and Implementation 2 does update min whenever a smaller value appears later in the array."},
  {"id": "4.5-intermediate-03", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to return the sum of all elements in an int array named data.\npublic static int arraySum(int[] data)\n{\n    int total;\n    for (int i = 0; i < data.length; i++)\n    {\n        total = total + data[i];\n    }\n    return total;\n}\nWhat is the problem with this method?", "choices": ["The loop condition should use <= instead of <, or the method will skip the last element.", "The variable total is never initialized before it is used in the loop, so the method will not compile.", "data[i] should be replaced with data[i + 1] so every element is included.", "The return type should be double instead of int to properly compute a sum."], "answer": 1, "explanation": "Local variables in Java are not automatically given a default value, so total must be explicitly initialized, typically to 0, before it is used in total = total + data[i]; without an initial value, this method fails to compile (4.5.A.1, sum algorithm). The loop condition i < data.length correctly visits every valid index without needing <=, data[i] already refers to the current element correctly, and there is no requirement that a sum of ints be returned as a double."},
  {"id": "4.5-intermediate-04", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to determine whether at least one element in an array of ints named readings is above 100.\npublic static boolean anyAboveLimit(int[] readings)\n{\n    boolean result = false;\n    for (int i = 0; i < readings.length; i++)\n    {\n        result = (readings[i] > 100);\n    }\n    return result;\n}\nWhat is the most accurate description of what this method actually returns?", "choices": ["Whether at least one element in readings is above 100, exactly as intended.", "Whether every element in readings is above 100.", "Whether only the last element in readings is above 100, since result is overwritten instead of accumulated each iteration.", "Whether the first element in readings is above 100."], "answer": 2, "explanation": "Because result is reassigned on every iteration rather than being combined with its previous value using an OR operation, result = (readings[i] > 100); simply overwrites any earlier true result, so only the outcome for the final element survives by the time the loop ends (4.5.A.1, at-least-one-element algorithm). This means the method fails to correctly detect an above-100 element that occurs anywhere except the last position; a correct version would use result = result || (readings[i] > 100);."},
  {"id": "4.5-intermediate-05", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Three candidate methods are proposed, each intended to determine whether an int array named data contains at least one value equal to target.\nCandidate I\nboolean found = false;\nfor (int i = 0; i < data.length; i++)\n{\n    found = found || (data[i] == target);\n}\nreturn found;\nCandidate II\nboolean found = false;\nfor (int i = 0; i < data.length; i++)\n{\n    if (data[i] == target)\n    {\n        return true;\n    }\n}\nreturn found;\nCandidate III\nboolean found = true;\nfor (int i = 0; i < data.length; i++)\n{\n    found = (data[i] == target);\n}\nreturn found;\nWhich candidate(s) correctly implement the at-least-one-element algorithm?", "choices": ["Candidate III only", "Candidates I and III only", "Candidate I only", "Candidates I and II only"], "answer": 3, "explanation": "Candidate I correctly accumulates matches with a logical OR across the whole traversal, and Candidate II correctly exits early with true the moment a match is found, returning false only if the loop completes without one (4.5.A.1). Candidate III initializes found to true instead of false and overwrites it every iteration instead of combining results, so it only reflects whether the last element happens to equal target, which does not correctly implement the intended algorithm."},
  {"id": "4.5-intermediate-06", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to determine whether every element in an int array named batchSizes is at least 10.\npublic static boolean allValid(int[] batchSizes)\n{\n    boolean valid = true;\n    for (int i = 0; i < batchSizes.length; i++)\n    {\n        if (batchSizes[i] >= 10)\n        {\n            valid = true;\n        }\n    }\n    return valid;\n}\nWhat is the flaw in this implementation of the all-elements algorithm?", "choices": ["valid should be initialized to false instead of true.", "The method never sets valid to false when an element fails the condition, so it always returns true regardless of the array's contents.", "The comparison should use > instead of >=.", "The loop should traverse the array backward instead of forward."], "answer": 1, "explanation": "The method only ever sets valid to true and never handles the case where an element fails the condition, so valid remains true from its initial value no matter what the array contains (4.5.A.1, all-elements algorithm). A correct version would set valid = false; (or return false immediately) when an element does not meet the condition. Initializing valid to false, changing the comparison operator, or reversing the traversal direction would not fix this fundamental logic error."},
  {"id": "4.5-intermediate-07", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to count how many elements in an int array named votes equal a given candidate number.\npublic static int countVotes(int[] votes, int candidate)\n{\n    int count = 0;\n    for (int i = 0; i < votes.length; i++)\n    {\n        if (votes[i] = candidate)\n        {\n            count++;\n        }\n    }\n    return count;\n}\nWhat is the problem with this method?", "choices": ["count should be initialized to 1 instead of 0.", "The loop should use <= instead of < in its condition.", "votes[i] = candidate uses the assignment operator instead of the equality operator ==, so the method will not compile as a valid boolean condition.", "count++ should be replaced with count = count + 2 to count votes correctly."], "answer": 2, "explanation": "An if condition must evaluate to a boolean, but votes[i] = candidate is an assignment of type int, not a boolean comparison, so this fails to compile; the condition should instead be votes[i] == candidate (4.5.A.1, counting algorithm). count correctly starts at 0, the loop condition i < votes.length correctly visits every valid index, and count++ correctly increments by exactly one for each match."},
  {"id": "4.5-intermediate-08", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Two implementations are proposed, each intended to count how many elements in an int array named inventory are equal to zero.\nImplementation 1\nint count = 0;\nfor (int i = 0; i < inventory.length; i++)\n{\n    if (inventory[i] == 0)\n    {\n        count++;\n    }\n}\nreturn count;\nImplementation 2\nint count = 0;\nfor (int i = 0; i < inventory.length; i++)\n{\n    if (inventory[i] == 0)\n    {\n        count = 1;\n    }\n}\nreturn count;\nWhich statement correctly compares these two implementations?", "choices": ["Both implementations return the same result for any array of at least one element.", "Implementation 2 is more efficient than Implementation 1 but returns the same result.", "Implementation 1 will throw an exception if inventory contains more than one zero.", "Implementation 1 correctly counts the number of zero elements, but Implementation 2 only ever reports whether at least one zero element exists, since it overwrites count with a fixed value of 1 instead of accumulating."], "answer": 3, "explanation": "Implementation 1 correctly increments count once for every zero found, matching the standard counting algorithm (4.5.A.1). Implementation 2 sets count to the constant value 1 whenever a zero is found instead of incrementing it, so it will report 1 whenever any zero exists (even if there are several) and 0 otherwise, which measures presence rather than quantity. Neither implementation throws an exception, and the two implementations are not equivalent in what they report."},
  {"id": "4.5-intermediate-09", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to count how many consecutive pairs of elements in an int array named levels are equal to each other.\npublic static int countEqualPairs(int[] levels)\n{\n    int count = 0;\n    for (int i = 0; i < levels.length; i++)\n    {\n        if (levels[i] == levels[i + 1])\n        {\n            count++;\n        }\n    }\n    return count;\n}\nWhat is the problem with this method?", "choices": ["The loop condition should be i < levels.length - 1 so that levels[i + 1] never indexes past the end of the array.", "count should be initialized to 1 instead of 0.", "levels[i + 1] should be replaced with levels[i - 1].", "The comparison operator == should be replaced with !=."], "answer": 0, "explanation": "When i reaches levels.length - 1, the expression levels[i + 1] attempts to access an index equal to levels.length, which is out of bounds and throws an ArrayIndexOutOfBoundsException; changing the loop condition to i < levels.length - 1 keeps every access to levels[i + 1] valid while still checking every consecutive pair (4.5.A.1). Initializing count to 1 or negating the comparison would not fix the out-of-bounds access, and replacing levels[i + 1] with levels[i - 1] would fail at i = 0 instead."},
  {"id": "4.5-intermediate-10", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Two implementations are proposed, each intended to determine the largest sum of any two consecutive elements in an int array named data, which contains at least two elements.\nImplementation 1\nint maxSum = data[0] + data[1];\nfor (int i = 0; i < data.length - 1; i++)\n{\n    int pairSum = data[i] + data[i + 1];\n    if (pairSum > maxSum)\n    {\n        maxSum = pairSum;\n    }\n}\nreturn maxSum;\nImplementation 2\nint maxSum = data[0] + data[1];\nfor (int i = 0; i < data.length; i++)\n{\n    int pairSum = data[i] + data[i + 1];\n    if (pairSum > maxSum)\n    {\n        maxSum = pairSum;\n    }\n}\nreturn maxSum;\nWhich statement correctly compares these two implementations?", "choices": ["Both implementations work as intended and produce identical results for every array.", "Implementation 2 works as intended, but Implementation 1 fails to check the final consecutive pair.", "Implementation 1 works as intended, but Implementation 2 will throw an ArrayIndexOutOfBoundsException when i reaches data.length - 1.", "Both implementations will throw an ArrayIndexOutOfBoundsException regardless of the array's contents."], "answer": 2, "explanation": "Implementation 1 correctly bounds the loop with data.length - 1, so data[i + 1] always refers to a valid index while every consecutive pair is checked (4.5.A.1). Implementation 2 uses the unbounded condition i < data.length, so when i equals data.length - 1, data[i + 1] attempts to access index data.length, which is out of bounds and throws an exception. Implementation 1 does check every consecutive pair, including the final one, so it does not miss any pair, and Implementation 1's correct loop bound means it never throws an exception."},
  {"id": "4.5-intermediate-11", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to determine whether an int array named codes contains any duplicate values.\npublic static boolean hasDuplicate(int[] codes)\n{\n    for (int i = 0; i < codes.length; i++)\n    {\n        for (int j = 0; j < codes.length; j++)\n        {\n            if (codes[i] == codes[j])\n            {\n                return true;\n            }\n        }\n    }\n    return false;\n}\nWhat is the flaw in this implementation of the duplicate-detection algorithm?", "choices": ["The inner loop should traverse codes in reverse order.", "The method should use two separate arrays instead of one.", "The outer loop's condition should use <= instead of <.", "When i and j are equal, codes[i] is compared to itself, which is always true, so the method incorrectly returns true even for an array with no actual duplicates."], "answer": 3, "explanation": "Because the inner loop starts at j = 0 instead of j = i + 1, the case i == j compares each element to itself, and codes[i] == codes[i] is always true, causing the method to immediately return true even when every element in the array is distinct (4.5.A.1, duplicate-detection algorithm). The correct fix is to start the inner loop at j = i + 1 so only distinct pairs of indices are compared. Reversing the inner loop's direction, using two arrays, or changing the outer loop's condition would not address this self-comparison bug."},
  {"id": "4.5-intermediate-12", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Two implementations are proposed, each intended to determine whether an int array named tags, which may be empty, contains any duplicate values.\nImplementation 1\nfor (int i = 0; i < tags.length; i++)\n{\n    for (int j = i + 1; j < tags.length; j++)\n    {\n        if (tags[i] == tags[j])\n        {\n            return true;\n        }\n    }\n}\nreturn false;\nImplementation 2\nfor (int i = 0; i < tags.length - 1; i++)\n{\n    for (int j = i + 1; j < tags.length; j++)\n    {\n        if (tags[i] == tags[j])\n        {\n            return true;\n        }\n    }\n}\nreturn false;\nWhich statement correctly compares these two implementations?", "choices": ["Both implementations correctly detect duplicates for every array, including an empty array, because the inner loop's condition j < tags.length prevents any out-of-bounds access in either version.", "Implementation 1 will throw an ArrayIndexOutOfBoundsException when tags is empty, but Implementation 2 will not.", "Implementation 2 will incorrectly miss a duplicate involving the very last element of tags.", "Implementation 1 is correct, but Implementation 2 will report a false duplicate for every array."], "answer": 0, "explanation": "In both versions, the inner loop's own condition, j < tags.length, is what actually prevents accessing an out-of-bounds index, so whether the outer loop's bound is tags.length or tags.length - 1 makes no difference to correctness: when i is the last index, the inner loop starting at i + 1 simply never executes in either implementation, and an empty array causes both outer loops to skip entirely (4.5.A.1). Neither implementation throws an exception, misses any duplicate pair, or reports duplicates that do not exist."},
  {"id": "4.5-intermediate-13", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to shift every element of an int array named buffer one position to the right, discarding the last element and placing a 0 in the first position.\npublic static void shiftRight(int[] buffer)\n{\n    for (int i = 0; i < buffer.length - 1; i++)\n    {\n        buffer[i + 1] = buffer[i];\n    }\n    buffer[0] = 0;\n}\nWhat is the problem with this method when it is tested on {5, 10, 15, 20}?", "choices": ["buffer[0] should be set to 0 before the loop runs instead of after.", "The loop traverses forward and overwrites each element with its neighbor's value before that original value is used elsewhere, corrupting the shift; the loop should instead traverse backward, copying from the last index down to index 1.", "The loop condition should be i <= buffer.length instead of i < buffer.length - 1.", "The method should return an int array instead of being void."], "answer": 1, "explanation": "Because the loop moves forward from i = 0, buffer[1] = buffer[0] first sets buffer[1] to 5, and then when i = 1, buffer[2] = buffer[1] copies the already-overwritten 5 instead of the original 10, so incorrect values cascade through the array. Traversing backward, from i = buffer.length - 1 down to i = 1, and assigning buffer[i] = buffer[i - 1], preserves each original value before it is overwritten (4.5.A.1, shift algorithm). Moving where buffer[0] = 0 executes does not fix the forward-overwrite bug, extending the loop condition would cause an out-of-bounds access, and the method's void return type is unrelated to the bug, since shifting is performed in place."},
  {"id": "4.5-intermediate-14", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "Two implementations are proposed, each intended to rotate the elements of an int array named ring one position to the left, so the first element wraps around to become the new last element. For example, {1, 2, 3, 4} should become {2, 3, 4, 1}.\nImplementation 1\nint first = ring[0];\nfor (int i = 0; i < ring.length - 1; i++)\n{\n    ring[i] = ring[i + 1];\n}\nring[ring.length - 1] = first;\nImplementation 2\nfor (int i = 0; i < ring.length - 1; i++)\n{\n    ring[i] = ring[i + 1];\n}\nring[ring.length - 1] = ring[0];\nWhich statement correctly compares these two implementations?", "choices": ["Both implementations correctly rotate the array in every case.", "Implementation 2 is correct, but Implementation 1 unnecessarily wastes memory by storing first.", "Implementation 1 will throw an ArrayIndexOutOfBoundsException, but Implementation 2 will not.", "Implementation 1 correctly rotates the array by saving the original first element before it is overwritten, but Implementation 2 incorrectly copies the already-shifted ring[0] (which by that point has been overwritten by the original ring[1]) into the last position instead of the true original first element."], "answer": 3, "explanation": "Implementation 1 saves the original first element in the variable first before the loop overwrites ring[0], so ring[ring.length - 1] = first; correctly places the true original first element at the end (4.5.A.1, shift/rotate algorithm). By the time Implementation 2 executes ring[ring.length - 1] = ring[0];, the loop has already overwritten ring[0] with the original ring[1], so it wraps around the wrong value instead of the array's true original first element. Neither implementation throws an exception, and Implementation 2's extra simplicity does not make it correct."},
  {"id": "4.5-intermediate-15", "course": "csa", "topic": "4.5", "tier": "intermediate", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to reverse the order of the elements in an int array named letters, an array of ints representing character codes, in place using swaps.\npublic static void reverseInPlace(int[] letters)\n{\n    for (int i = 0; i < letters.length / 2; i++)\n    {\n        int temp = letters[i];\n        letters[i] = letters[letters.length - i];\n        letters[letters.length - i] = temp;\n    }\n}\nWhat is the problem with this method?", "choices": ["The expressions letters[letters.length - i] should instead be letters[letters.length - i - 1]; as written, the method accesses an index equal to letters.length when i is 0, which is out of bounds.", "The loop should traverse the full array instead of stopping at letters.length / 2.", "temp should be declared outside the loop instead of inside it.", "The swap should use three separate temp variables instead of one."], "answer": 0, "explanation": "When i is 0, letters[letters.length - i] evaluates to letters[letters.length], which is one index past the end of the array and throws an ArrayIndexOutOfBoundsException; the correct index pairing with letters[i] is letters[letters.length - i - 1] (4.5.A.1, reverse algorithm). Stopping the loop at letters.length / 2 is intentional and correct, since swapping past the midpoint would undo the swaps already made; declaring temp inside the loop is proper practice since a fresh temp is needed each iteration, and only one temp variable is ever needed to perform a swap."},
  {"id": "4.5-complex-01", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student proposes five candidate methods, each intended to return the index of the smallest value in an int array named data, which contains at least one element.\nCandidate I\nint minIndex = 0;\nfor (int i = 1; i < data.length; i++)\n{\n    if (data[i] < data[minIndex])\n    {\n        minIndex = i;\n    }\n}\nreturn minIndex;\nCandidate II\nint minIndex = 0;\nfor (int i = 0; i < data.length; i++)\n{\n    if (data[i] < minIndex)\n    {\n        minIndex = i;\n    }\n}\nreturn minIndex;\nCandidate III\nint minIndex = data.length - 1;\nfor (int i = data.length - 2; i >= 0; i--)\n{\n    if (data[i] < data[minIndex])\n    {\n        minIndex = i;\n    }\n}\nreturn minIndex;\nCandidate IV\nint minIndex = 0;\nfor (int i = 1; i < data.length; i++)\n{\n    if (data[minIndex] < data[i])\n    {\n        minIndex = i;\n    }\n}\nreturn minIndex;\nCandidate V\nint minIndex = 0;\nfor (int i = 1; i <= data.length; i++)\n{\n    if (data[i] < data[minIndex])\n    {\n        minIndex = i;\n    }\n}\nreturn minIndex;\nWhich candidates correctly return the index of the smallest value for every valid array?", "choices": ["Candidates I, II, and III only", "Candidates I and III only", "Candidates I, III, and IV only", "Candidates I, III, and V only"], "answer": 1, "explanation": "Candidate I implements the standard forward minimum-index algorithm correctly, and Candidate III does the same by traversing backward from the last index, still comparing data[i] to data[minIndex] at every step, so both correctly return the index of the smallest value for every valid array (4.5.A.1). Candidate II compares data[i] to the index minIndex itself rather than to data[minIndex], Candidate IV's comparison direction actually tracks the index of the largest value rather than the smallest, and Candidate V's loop condition i <= data.length causes an ArrayIndexOutOfBoundsException when i equals data.length."},
  {"id": "4.5-complex-02", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A fitness app stores daily step counts in an int array named steps. A method is intended to return an int array runningTotal such that runningTotal[i] equals the sum of steps[0] through steps[i] for every index i. For example, if steps contains {2000, 500, 1500}, runningTotal should contain {2000, 2500, 4000}. Two implementations of the missing code are proposed, both starting from an array runningTotal already created and filled with zeros.\nImplementation 1\nfor (int i = 0; i < steps.length; i++)\n{\n    runningTotal[i] = runningTotal[i - 1] + steps[i];\n}\nImplementation 2\nfor (int i = 0; i < steps.length; i++)\n{\n    for (int k = 0; k <= i; k++)\n    {\n        runningTotal[i] = runningTotal[i] + steps[k];\n    }\n}\nWhich statement is true about these two implementations?", "choices": ["Both implementations work as intended, and Implementation 2 is faster than Implementation 1.", "Both implementations work as intended, and Implementation 1 is faster than Implementation 2.", "Implementation 1 will throw an ArrayIndexOutOfBoundsException, because runningTotal[i - 1] accesses index -1 when i is 0; Implementation 2 works as intended, but is less efficient because of its nested loop.", "Implementation 2 will throw an ArrayIndexOutOfBoundsException, but Implementation 1 works as intended."], "answer": 2, "explanation": "When i is 0, Implementation 1 evaluates runningTotal[i - 1], which is runningTotal[-1], an invalid index that throws an ArrayIndexOutOfBoundsException before any running total can be computed (4.5.A.1, sum/consecutive-pairs style running-total algorithm). Implementation 2 correctly recomputes the sum of steps[0] through steps[i] from scratch for every i using a nested loop, so it works as intended, but this repeated inner summation is less efficient than a single accumulating pass would be. Implementation 1's -1 index access means it never completes successfully, so neither the claim that both work nor the claim that Implementation 1 is faster can be true; Implementation 2 itself never accesses an invalid index."},
  {"id": "4.5-complex-03", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "Three candidate methods are proposed, each intended to compute the average of the elements in an array that could potentially be empty, having a length of 0.\nCandidate I\npublic static double average(double[] values)\n{\n    double sum = 0;\n    for (int i = 0; i < values.length; i++)\n    {\n        sum = sum + values[i];\n    }\n    return sum / values.length;\n}\nCandidate II\npublic static double average(int[] values)\n{\n    int sum = 0;\n    for (int i = 0; i < values.length; i++)\n    {\n        sum = sum + values[i];\n    }\n    return sum / values.length;\n}\nCandidate III\npublic static double average(double[] values)\n{\n    double sum = 0;\n    for (int i = 0; i <= values.length; i++)\n    {\n        sum = sum + values[i];\n    }\n    return sum / values.length;\n}\nWhich statement is true about these candidates when each is called with an empty array?", "choices": ["Candidate I returns a value of Infinity or NaN rather than throwing an exception, Candidate II throws an ArithmeticException due to integer division by zero, and Candidate III throws an ArrayIndexOutOfBoundsException because its loop condition allows i to equal values.length.", "All three candidates throw the same type of exception when given an empty array.", "Candidate I throws an exception, but Candidates II and III do not.", "Only Candidate III behaves correctly with an empty array; Candidates I and II both throw exceptions."], "answer": 0, "explanation": "In Java, dividing a double by 0, as in Candidate I, does not throw an exception; it instead produces a special floating-point result such as NaN or Infinity, since values.length is 0 (4.5.A.1, sum/average algorithm). Candidate II divides an int sum by an int length of 0, which does trigger an ArithmeticException at runtime. Candidate III's loop condition i <= values.length allows i to reach values.length itself, which is one past the last valid index, causing an ArrayIndexOutOfBoundsException regardless of whether the array is empty. No two of these three candidates fail, or succeed, in the same way, so only the option distinguishing all three behaviors correctly is accurate."},
  {"id": "4.5-complex-04", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "Five candidate methods are proposed, each intended to determine whether at least one element in an int array named sensorReadings is greater than a threshold value called limit.\nCandidate I\nboolean flag = false;\nfor (int i = 0; i < sensorReadings.length; i++)\n{\n    if (sensorReadings[i] > limit)\n    {\n        flag = true;\n    }\n}\nreturn flag;\nCandidate II\nfor (int i = 0; i < sensorReadings.length; i++)\n{\n    if (sensorReadings[i] > limit)\n    {\n        return true;\n    }\n}\nreturn false;\nCandidate III\nboolean flag = true;\nfor (int i = 0; i < sensorReadings.length; i++)\n{\n    flag = flag && (sensorReadings[i] > limit);\n}\nreturn flag;\nCandidate IV\nboolean flag = false;\nfor (int i = 0; i < sensorReadings.length; i++)\n{\n    flag = (sensorReadings[i] > limit);\n}\nreturn flag;\nCandidate V\nboolean flag = false;\nfor (int i = 0; i < sensorReadings.length; i++)\n{\n    flag = flag || (sensorReadings[i] > limit);\n}\nreturn flag;\nWhich candidates correctly implement the at-least-one-element algorithm for every possible array?", "choices": ["Candidates I and II only", "Candidates I, II, and V only", "Candidates II and V only", "Candidates I, III, and V only"], "answer": 1, "explanation": "Candidate I never resets flag back to false once it becomes true and correctly stays true if any element exceeds limit; Candidate II exits early with true the moment a qualifying element is found; and Candidate V correctly accumulates matches using a logical OR across the traversal, so all three correctly implement the at-least-one-element algorithm (4.5.A.1). Candidate III uses a logical AND, which actually tests whether every element exceeds limit, not whether at least one does, and Candidate IV overwrites flag on every iteration instead of accumulating, so it only reflects whether the very last element exceeds limit."},
  {"id": "4.5-complex-05", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "Four candidate methods are proposed, each intended to determine whether every element in an int array named batch is positive, greater than 0, including correctly handling the case where batch is empty.\nCandidate I\nfor (int i = 0; i < batch.length; i++)\n{\n    if (batch[i] <= 0)\n    {\n        return false;\n    }\n}\nreturn true;\nCandidate II\nboolean allPositive = true;\nfor (int i = 0; i < batch.length; i++)\n{\n    allPositive = allPositive && (batch[i] > 0);\n}\nreturn allPositive;\nCandidate III\nboolean allPositive = false;\nfor (int i = 0; i < batch.length; i++)\n{\n    if (batch[i] > 0)\n    {\n        allPositive = true;\n    }\n}\nreturn allPositive;\nCandidate IV\nboolean allPositive = true;\nfor (int i = 0; i < batch.length; i++)\n{\n    allPositive = (batch[i] > 0);\n}\nreturn allPositive;\nWhich candidates correctly return true when batch is empty and correctly implement the all-elements algorithm for every array?", "choices": ["Candidate I only", "Candidates II and IV only", "Candidates I and II only", "Candidates I, II, and III only"], "answer": 2, "explanation": "Candidate I uses the standard early-exit all-elements algorithm: it returns false the instant an element fails the condition and otherwise falls through to return true, which correctly yields true on an empty array since the loop body never executes (4.5.A.1). Candidate II uses a logical AND to accumulate the condition across every element, which is equivalent in effect to Candidate I and likewise yields true for an empty array. Candidate III actually implements the at-least-one-element algorithm rather than all-elements, and incorrectly returns false for an empty array since allPositive starts false, and Candidate IV overwrites allPositive on every iteration instead of accumulating, so for any non-empty array it only reflects whether the last element is positive."},
  {"id": "4.5-complex-06", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "An array of Strings named entries stores user-submitted codes. A method is intended to determine whether every entry in entries is equal to the String \"OK\".\npublic static boolean allOK(String[] entries)\n{\n    for (int i = 0; i < entries.length; i++)\n    {\n        if (entries[i] != \"OK\")\n        {\n            return false;\n        }\n    }\n    return true;\n}\nA classmate says this method works correctly. Which statement best evaluates the classmate's claim, given how == and != behave with String objects in Java?", "choices": ["The classmate is correct; != is the appropriate way to compare String content in Java.", "The classmate is correct, because entries[i] != \"OK\" will always evaluate the same as entries[i].equals(\"OK\") == false.", "The classmate is incorrect; the loop bound should be entries.length - 1 instead of entries.length.", "The classmate is incorrect; entries[i] != \"OK\" compares object references rather than String content, so the method may incorrectly return false for a String that has the same characters as \"OK\" but was constructed as a separate object, rather than correctly implementing the all-elements algorithm based on content equality."], "answer": 3, "explanation": "The all-elements algorithm here is meant to check content equality, but != (and ==) on String objects in Java compares object references, not the sequence of characters, so entries[i] != \"OK\" can incorrectly evaluate to true, indicating a mismatch, even when entries[i] contains the exact same characters as \"OK\", if it was created as a distinct String object (4.5.A.1). The correct condition should be !entries[i].equals(\"OK\"). The loop bound entries.length is already correct for visiting every element, and reference comparison does not reliably behave the same as .equals() for Strings constructed separately from a literal."},
  {"id": "4.5-complex-07", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to count how many elements in an int array named orders are between 10 and 20, inclusive on both ends.\npublic static int countInRange(int[] orders)\n{\n    int count = 0;\n    for (int i = 0; i < orders.length; i++)\n    {\n        int count2 = 0;\n        if (orders[i] >= 10 && orders[i] <= 20)\n        {\n            count2++;\n        }\n        count = count2;\n    }\n    return count;\n}\nWhat is the flaw in this implementation of the counting algorithm?", "choices": ["The condition should use || instead of && to combine the two bounds.", "count2 is declared and reset to 0 inside the loop on every iteration, and count is overwritten with count2 rather than accumulated, so the method only reflects whether the last element qualifies, 0 or 1, not the total count.", "orders[i] <= 20 should be replaced with orders[i] < 20.", "count should be declared as a double instead of an int."], "answer": 1, "explanation": "Because count2 is declared inside the loop, it is reset to 0 at the start of every iteration, and count = count2; overwrites the running count with either 0 or 1 based only on the current element, discarding any accumulation from previous iterations; the correct algorithm should increment a single counter declared outside the loop (4.5.A.1, counting algorithm). The && operator correctly requires both bounds to hold simultaneously, changing <= to < would incorrectly exclude the value 20 from an inclusive range, and there is no need for count to be a double since it represents a whole-number tally."},
  {"id": "4.5-complex-08", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student is writing a method intended to return an int array named diffs, where diffs[i] equals data[i + 1] - data[i] for each valid consecutive pair in an int array named data, so diffs should have one fewer element than data. Two implementations of the method body are proposed, both starting from an int array diffs already created with length data.length - 1.\nImplementation 1\nfor (int i = 0; i < data.length; i++)\n{\n    diffs[i] = data[i + 1] - data[i];\n}\nImplementation 2\nfor (int i = 0; i < data.length - 1; i++)\n{\n    diffs[i] = data[i + 1] - data[i];\n}\nWhich statement is true about these two implementations?", "choices": ["Both implementations work as intended for every array of at least two elements.", "Implementation 1 works as intended, but Implementation 2 fails to compute the final difference.", "Implementation 1 will throw an ArrayIndexOutOfBoundsException on its final iteration, because both data[i + 1] and diffs[i] are accessed one index beyond their valid bounds; Implementation 2 correctly stops before that point and works as intended.", "Both implementations will throw an ArrayIndexOutOfBoundsException regardless of the contents of data."], "answer": 2, "explanation": "Implementation 1's loop runs while i < data.length, so on its last iteration i equals data.length - 1; at that point evaluating the right-hand side data[i + 1] - data[i] accesses data[data.length], which is out of bounds, so an ArrayIndexOutOfBoundsException is thrown right there, before the equally invalid store into diffs[i] (which is also one past its last valid index) is ever attempted (4.5.A.1, consecutive-pairs algorithm). Implementation 2 correctly bounds the loop with data.length - 1, so i never exceeds data.length - 2, keeping both data[i + 1] and diffs[i] within valid bounds while still computing every consecutive difference, including the final one."},
  {"id": "4.5-complex-09", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to return the length of the longest consecutive run of the same value in an int array named signal. For example, if signal contains {5, 5, 5, 2, 2, 7, 7, 7, 7}, the method should return 4, the length of the run of 7s.\npublic static int longestRun(int[] signal)\n{\n    int runLength = 1;\n    int maxRun = 1;\n    for (int i = 1; i < signal.length; i++)\n    {\n        if (signal[i] == signal[i - 1])\n        {\n            runLength++;\n        }\n        else\n        {\n            runLength = 1;\n        }\n        if (runLength > maxRun)\n        {\n            maxRun = runLength;\n        }\n    }\n    return maxRun;\n}\nWhat value does longestRun return when it is called on {5, 5, 5, 2, 2, 7, 7, 7, 7}?", "choices": ["3", "2", "9", "4"], "answer": 3, "explanation": "This method correctly implements the consecutive-pairs based run-length algorithm (4.5.A.1): it compares each element to its predecessor, extending runLength when they match and resetting it to 1 when they differ, updating maxRun after every comparison so the check happens both during and at the end of each run. Tracing the array, the run of three 5s reaches a runLength of 3, the run of two 2s reaches 2, and the run of four 7s reaches a runLength of 4, which becomes the final maxRun. 3 and 2 are the lengths of the earlier, shorter runs, and 9 is simply the length of the entire array, not the longest run within it."},
  {"id": "4.5-complex-10", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to determine whether an int array named batchIDs contains any duplicate values, using only a single pass with no nested loop.\npublic static boolean hasAdjacentDuplicate(int[] batchIDs)\n{\n    for (int i = 0; i < batchIDs.length - 1; i++)\n    {\n        if (batchIDs[i] == batchIDs[i + 1])\n        {\n            return true;\n        }\n    }\n    return false;\n}\nA classmate claims this method correctly detects whether batchIDs contains any duplicate values anywhere in the array. Which statement best evaluates this claim?", "choices": ["The classmate is incorrect; this method only detects duplicates that occur in immediately consecutive positions, so it would incorrectly return false for an array like {3, 8, 3, 9}, which contains a duplicate 3 that is not adjacent.", "The classmate is correct, because any array containing a duplicate must have that duplicate appear in consecutive positions.", "The classmate is incorrect, because the method will throw an ArrayIndexOutOfBoundsException for any array of more than one element.", "The classmate is correct, because the loop condition batchIDs.length - 1 guarantees every pair of elements in the array is compared."], "answer": 0, "explanation": "This method only compares each element to its immediate neighbor, so it correctly detects the standard consecutive-pairs pattern of adjacent equal values, but it is not a general duplicate-detection algorithm (4.5.A.1): a full duplicate check requires comparing every pair of elements, not just adjacent ones, typically with a nested loop. For {3, 8, 3, 9}, the two 3s are not adjacent, so the method never compares them and incorrectly returns false. The loop's bound is correctly chosen to avoid an out-of-bounds access, and it does not compare every possible pair, since it never compares batchIDs[0] to batchIDs[2], for example, only to batchIDs[1]."},
  {"id": "4.5-complex-11", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to determine whether an int array named tickets contains any duplicate values.\npublic static boolean hasDuplicate(int[] tickets)\n{\n    int i = 0;\n    while (i < tickets.length)\n    {\n        int j = i + 1;\n        while (j < tickets.length)\n        {\n            if (tickets[i] == tickets[j])\n            {\n                return true;\n            }\n        }\n        i++;\n    }\n    return false;\n}\nUnder which condition will a call to hasDuplicate fail to terminate?", "choices": ["It will always terminate correctly, regardless of the contents of tickets.", "It will fail to terminate only when tickets contains no duplicate values at all.", "It will fail to terminate whenever tickets.length is greater than 1 and tickets[i] does not equal tickets[i + 1] the first time the inner loop runs, because j is never incremented inside the inner while loop.", "It will fail to terminate only when every element of tickets is identical."], "answer": 2, "explanation": "The inner while loop's condition, j < tickets.length, and the value of j never change inside the loop body unless the if branch happens to return immediately, since j is never incremented; if tickets[i] and tickets[j] are not equal the first time through, the same comparison repeats forever, causing an infinite loop (4.5.A.1, duplicate-detection algorithm). This means the method only terminates normally in the narrow case where tickets[i] happens to equal tickets[i + 1] right away, not the reverse of that condition, and it does not always terminate, nor does its failure to terminate depend on every element being identical or on there being no duplicates at all."},
  {"id": "4.5-complex-12", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to rotate the elements of an int array named schedule left by exactly 2 positions, wrapping the first two elements around to the end. For example, {10, 20, 30, 40, 50} should become {30, 40, 50, 10, 20}.\npublic static void rotateLeftByTwo(int[] schedule)\n{\n    int[] result = new int[schedule.length];\n    for (int i = 0; i < schedule.length; i++)\n    {\n        result[i] = schedule[(i + 2) % schedule.length];\n    }\n    for (int i = 0; i < schedule.length; i++)\n    {\n        schedule[i] = result[i];\n    }\n}\nWhat are the contents of schedule after rotateLeftByTwo is called on {10, 20, 30, 40, 50}?", "choices": ["{40, 50, 10, 20, 30}", "{50, 10, 20, 30, 40}", "{10, 20, 30, 40, 50}", "{30, 40, 50, 10, 20}"], "answer": 3, "explanation": "This method correctly implements the shift/rotate algorithm using the modulo operator to wrap indices around (4.5.A.1): result[i] is filled with schedule[(i + 2) % schedule.length], so result[0] takes schedule[2], 30, result[1] takes schedule[3], 40, and so on, wrapping around so result[3] takes schedule[5 % 5] = schedule[0], 10, and result[4] takes schedule[1], 20, giving {30, 40, 50, 10, 20}. {40, 50, 10, 20, 30} would result from rotating left by 3 instead of 2, {50, 10, 20, 30, 40} would result from rotating left by 4, and {10, 20, 30, 40, 50} is the unrotated original array."},
  {"id": "4.5-complex-13", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student writes the following method, intended to reverse the order of the elements in an int array named queue using in-place swaps.\npublic static void reverseInPlace(int[] queue)\n{\n    for (int k = 0; k < queue.length; k++)\n    {\n        int temp = queue[k];\n        queue[k] = queue[queue.length - 1 - k];\n        queue[queue.length - 1 - k] = temp;\n    }\n}\nWhat are the contents of queue after reverseInPlace is called on {1, 2, 3, 4}?", "choices": ["{1, 2, 3, 4}", "{4, 3, 2, 1}", "{4, 2, 3, 1}", "{2, 1, 4, 3}"], "answer": 0, "explanation": "Because the loop runs across the entire array instead of stopping at the midpoint, each swap performed early in the traversal is undone by an identical swap performed later: swapping indices 0 and 3 when k = 0 is undone when k = 3 swaps the same two indices back, and swapping indices 1 and 2 when k = 1 is undone when k = 2 swaps them back, leaving the array exactly as it started, {1, 2, 3, 4} (4.5.A.1, reverse algorithm). The correct loop bound should be queue.length / 2 so each pair is swapped exactly once. {4, 3, 2, 1} is the correctly reversed array that would result from the intended fix, and the remaining two options do not match a full undo of every swap."},
  {"id": "4.5-complex-14", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "Two implementations are proposed, each intended to reverse the elements of an int array named panel in place using swaps, for arrays of any length, including odd lengths.\nImplementation 1\nfor (int k = 0; k < panel.length / 2; k++)\n{\n    int temp = panel[k];\n    panel[k] = panel[panel.length - 1 - k];\n    panel[panel.length - 1 - k] = temp;\n}\nImplementation 2\nfor (int k = 0; k <= panel.length / 2; k++)\n{\n    int temp = panel[k];\n    panel[k] = panel[panel.length - 1 - k];\n    panel[panel.length - 1 - k] = temp;\n}\nWhich statement correctly compares these two implementations when panel has an odd length, such as 5?", "choices": ["Implementation 2 will throw an ArrayIndexOutOfBoundsException for every odd-length array.", "Implementation 1 correctly reverses the array by stopping exactly at the midpoint; Implementation 2 performs one extra iteration at the middle index, which harmlessly swaps the middle element with itself and still produces a correctly reversed array.", "Implementation 1 fails to reverse the middle element, producing an incorrectly reversed array.", "Both implementations fail to reverse arrays of odd length."], "answer": 1, "explanation": "For an odd length such as 5, integer division gives panel.length / 2 = 2, so Implementation 1's loop runs for k = 0 and k = 1, correctly swapping the two outer pairs of indices while leaving the middle index untouched, which is exactly correct since the middle element of an odd-length array does not need to move (4.5.A.1, reverse algorithm). Implementation 2's loop condition k <= panel.length / 2 allows one additional iteration at k = 2, which swaps panel[2] with panel[5 - 1 - 2] = panel[2], swapping the middle element with itself; this extra step changes nothing and the array is still correctly reversed. Neither implementation throws an exception, and the middle element is correctly left in place by Implementation 1 rather than mishandled."},
  {"id": "4.5-complex-15", "course": "csa", "topic": "4.5", "tier": "complex", "lo": "4.5.A.1", "prompt": "A student attempts to reverse an int array named panelIDs in place using an enhanced for loop.\npublic static void reversePanel(int[] panelIDs)\n{\n    int i = panelIDs.length - 1;\n    for (int value : panelIDs)\n    {\n        panelIDs[i] = value;\n        i--;\n    }\n}\nWhich statement best evaluates whether this implements the standard reverse algorithm correctly?", "choices": ["It works correctly because the enhanced for loop still visits every element of panelIDs exactly once, in order.", "It fails only when panelIDs has an even number of elements.", "It fails only when panelIDs has an odd number of elements.", "It does not reliably reverse the array, because writing to panelIDs[i] partway through the traversal can overwrite an element before the enhanced for loop has read its original value later in the same traversal."], "answer": 3, "explanation": "Although the enhanced for loop does read each original value in order, the loop simultaneously writes that value into panelIDs[i] where i counts down from the end; once i passes the midpoint, these writes begin overwriting elements that the enhanced for loop has not yet reached, so the value variable can be assigned an already-modified element instead of the true original value (4.5.A.1, reverse algorithm). This corruption happens for arrays of any length once the write and read positions cross, not only for even-length or odd-length arrays specifically, so the method does not reliably implement the standard reverse algorithm despite visiting every index."},
];
